const e=[{id:"movies-001",text:"Leave something for someone but don't leave someone for something.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"easy",length:66},{id:"movies-002",text:"If you have to ask, you will never know. If you know, you need only ask.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"easy",length:72},{id:"movies-003",text:"Yeah it's you, you're the one that makes me feel right. I've been in love with her for ages and I can't seem to get it right. I fell in love with her in stages my whole life.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:174},{id:"movies-004",text:"Cleaning your house while kids are around is like shoveling the walk while it's still snowing.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:94},{id:"movies-005",text:"You know when I was a kid I always wanted to be a cowboy, and now knowing I'm going to spend my future in the past sounds like a wonderful way to spend my retirement years.",author:"",source:"Back to the Future",category:"movies",license:"Fair Use",difficulty:"hard",length:172},{id:"movies-006",text:"You must learn from the mistakes of others because you can't possibly live long enough to make them all yourself.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:113},{id:"movies-007",text:"Those who have made something of their lives will always look at those who haven't as clowns.",author:"",source:"Joker",category:"movies",license:"Fair Use",difficulty:"medium",length:93},{id:"movies-008",text:"Sometimes life is like this dark tunnel. You can't always see the light at the end of the tunnel, but if you just keep moving, you will come to a better place.",author:"",source:"Avatar",category:"movies",license:"Fair Use",difficulty:"hard",length:159},{id:"movies-009",text:"I know it's a mistake. But there are certain things in life where you know it's a mistake, but you don't really know it's a mistake, because the only way to really know it's a mistake is to make the mistake.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:207},{id:"movies-010",text:"No one really knows why they're alive until they know what they'd die for.",author:"Martin Luther King Jr.",source:"Her",category:"movies",license:"Fair Use",difficulty:"easy",length:74},{id:"movies-011",text:"No matter where you stand on the long path, right now, try very hard to smile, and be glad you're in the game.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:110},{id:"movies-012",text:"The thing about a story is that you dream it as you tell it, hoping that others might then dream along with you, and in this way memory and imagination and language combine to make spirits in the head. There is the illusion of aliveness.",author:"",source:"The Thing",category:"movies",license:"Fair Use",difficulty:"hard",length:237},{id:"movies-013",text:"I never wanted that. Of course, it's one thing not to want something; it's another to be told you can't have it. I guess it's just nice knowing that you could someday do it if you change your mind. But now, all of a sudden, that door is closed.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:244},{id:"movies-014",text:"You can always build a shrine to all the terrible things in the world, but it doesn't mean that you have to destroy anything that is good.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:138},{id:"movies-015",text:"Any man who has the brains to think and the nerve to act for the benefit of the people of the country is considered a radical, by those who are content with stagnation and willing to endure disaster.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:199},{id:"movies-016",text:"When it's coming at you like monsters in the night, and you feel the danger that makes you want to hide; when the cards are stacked against you and you're standing on the edge: now's the time.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:192},{id:"movies-017",text:"Well, we used to look up in the sky and wonder at our place in the stars. Now we just look down and worry about our place in the dirt.",author:"",source:"Interstellar",category:"movies",license:"Fair Use",difficulty:"medium",length:134},{id:"movies-018",text:"The law clearly states that magic may be used before Muggles in life-threatening situations.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"medium",length:92},{id:"movies-019",text:"Why would you pay for a cover band when you got the real deal right here, baby?",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"easy",length:79},{id:"movies-020",text:"The hills are alive with the sound of music, with songs they have sung for a thousand years. The hills fill my heart with the sound of music. My heart wants to sing every song it hears.",author:"",source:"The Sound of Music",category:"movies",license:"Fair Use",difficulty:"hard",length:185},{id:"movies-021",text:"I was once like you are now, and I know that it's not easy to be calm when you've found something going on. But take your time, think a lot. I think of everything you've got, for you will still be here tomorrow but your dreams may not.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:235},{id:"movies-022",text:"When you meet the right person, you know it. You can't stop thinking about them. They are your best friend, and your soulmate. You can't wait to spend the rest of your life with them. No one and nothing else can compare.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:220},{id:"movies-023",text:"People don't suffer from insanity, they love every minute of it.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"easy",length:64},{id:"movies-024",text:"With the money they earn they'll be able to buy more police and political power. Then they come after us. Right now we have the unions and we have the gambling and those are the best things to have.",author:"",source:"The Godfather",category:"movies",license:"Fair Use",difficulty:"hard",length:198},{id:"movies-025",text:"They say that money doesn't bring you happiness, I say neither does being broke, so let me suffer with a new car.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:113},{id:"movies-026",text:"You have a class of young strong men and women, and they want to give their lives to something. Advertising has these people chasing cars and clothes they don't need. Generations have been working in jobs they hate, just so they can buy what they don't really need.",author:"",source:"Fight Club",category:"movies",license:"Fair Use",difficulty:"hard",length:265},{id:"movies-027",text:"You and Marshall belong together. The two of you have something most people search their whole lives for and never find. I know you love him and if you knew what he was going through right now you wouldn't be here for one more second. I bought you a ticket home. Marshall is one of the best people I know and it won't be long until someone else realizes that and you will lose him forever.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:389},{id:"movies-028",text:"I want to leave my footprints in the sands of time. Know there was something that meant something that I left behind. The hearts I have touched will be the proof that I leave that I made a difference and this world will see I was here.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:235},{id:"movies-029",text:"As a young child my mother told me I could be anyone I want to be. Turns out this is called identity theft.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:107},{id:"movies-030",text:"Just because something bears the aspect of the inevitable one should not, therefore, go along willingly with it.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:112},{id:"movies-031",text:"Your future hasn't been written yet; no one's has. Your future is whatever you make it, so make it a good one.",author:"",source:"Back to the Future",category:"movies",license:"Fair Use",difficulty:"medium",length:110},{id:"movies-032",text:"You are the true master of death, because the true master does not seek to run away from Death. He accepts that he must die, and understands that there are far, far worse things in the living world than dying.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:209},{id:"movies-033",text:"You can tell from the lines on her face, you can see that she's been there. Probably been moved on from every place 'cause she didn't fit in there.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:147},{id:"movies-034",text:"I would never want to belong to any club that would have someone like me as a member. That's the key joke of my adult life in terms of my relationships with women.",author:"",source:"Annie Hall",category:"movies",license:"Fair Use",difficulty:"hard",length:163},{id:"movies-035",text:"Working hard is important, but there's something that matters even more, believing in yourself. Think of it this way, every great wizard in history has started out as nothing more than what we are now, students. If they can do it, why not us.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:242},{id:"movies-036",text:"So you were born, and that was a good day. Someday you'll die, and that is a shame. But somewhere in the between was a life in which we all dream. And nothing and no one will ever take that away.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:195},{id:"movies-037",text:"Five thousand of my men are out there in the freezing mud. Three thousand of them are bloodied and cleaved. Two thousand will never leave this place. I will not believe they fought and died for nothing.",author:"",source:"Gladiator",category:"movies",license:"Fair Use",difficulty:"hard",length:202},{id:"movies-038",text:"I do not know what evil is when it comes to art. I only know what is good art and what is bad art.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:98},{id:"movies-039",text:"You had to kill the conversation, you always had the upper hand. Got caught in love and stepped in sinking sand. You had to go and ruin all our plans, packed your bags and you're leaving home. Got a one-way ticket and you're all set to go, but we have one more day together, so love me like there's no tomorrow.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:311},{id:"movies-040",text:"Last night we said a great many things. You said I was to do the thinking for both of us. Well, I've done a lot of it since then, and it all adds up to one thing: you're getting on that plane with Victor where you belong.",author:"",source:"Casablanca",category:"movies",license:"Fair Use",difficulty:"hard",length:221},{id:"movies-041",text:"It's just that I learned a while ago that the best way to get people to like you is not to like them too much.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:110},{id:"movies-042",text:"You are the promised kiss of springtime that makes the lonely winter seem long. You are the breathless hush of evening that trembles on the brink of a lovely song. You are the angel glow that lights a star, the dearest things I know are what you are. Some day my happy arms will hold you, and some day I'll know that moment divine when all the things you are, are mine.",author:"",source:"The Thing",category:"movies",license:"Fair Use",difficulty:"hard",length:369},{id:"movies-043",text:"I've never been to this part of the castle, at least while awake. I sleepwalk you see, that's why I wear shoes to bed.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"medium",length:118},{id:"movies-044",text:"There's a storm coming, Mr. Wayne. You and your friends better batten down the hatches, because when it hits, you're all gonna wonder how you ever thought you could live so large and leave so little for the rest of us.",author:"",source:"The Dark Knight",category:"movies",license:"Fair Use",difficulty:"hard",length:218},{id:"movies-045",text:"Everyone gets everything he wants. I wanted a mission, and for my sins, they gave me one. Brought it up to me like room service. It was a real choice mission, and when it was over, I never wanted another.",author:"",source:"Apocalypse Now",category:"movies",license:"Fair Use",difficulty:"hard",length:204},{id:"movies-046",text:"My heart wants to beat like the wings of the birds that rise from the lake to the trees. My heart wants to sigh like a chime that flies from a church on a breeze, to laugh like a brook when it trips and falls over stones on its way, to sing through the night like a lark who is learning to pray.",author:"",source:"The Sound of Music",category:"movies",license:"Fair Use",difficulty:"hard",length:295},{id:"movies-047",text:"You'll never have that kind of relationship in a world where you're afraid to take the first step because all you see is every negative thing ten miles down the road.",author:"",source:"Good Will Hunting",category:"movies",license:"Fair Use",difficulty:"hard",length:166},{id:"movies-048",text:"The thing under my bed waiting to grab my ankle isn't real. I know that, and I also know that if I'm careful to keep my foot under the covers, it will never be able to grab my ankle.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:182},{id:"movies-049",text:"You know when I was your age, I went out to fishing with all my brothers and my father, and everybody. And I was the only one who caught a fish.",author:"",source:"The Godfather",category:"movies",license:"Fair Use",difficulty:"medium",length:144},{id:"movies-050",text:"If all these dreams might find their way into my day to day scene I'd be under the impression I was somewhere in between. With only two, just me and you. Not so many things we got to do or places we got to be.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:209},{id:"movies-051",text:"I'll tell you a riddle. You're waiting for a train, a train that will take you far away. You know where you hope this train will take you, but you don't know for sure. But it doesn't matter. How can it not matter to you where that train will take you?",author:"",source:"Inception",category:"movies",license:"Fair Use",difficulty:"hard",length:251},{id:"movies-052",text:"I suppose it is tempting, if the only tool you have is a hammer, to treat everything as if it were a nail.",author:"",source:"Psycho",category:"movies",license:"Fair Use",difficulty:"medium",length:106},{id:"movies-053",text:"All of these moments just might find their way into my dreams tonight. But I know that they'll be gone when the morning light sings and brings new things.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:154},{id:"movies-054",text:"Someone once told me that time was a predator that stalked us all our lives. I rather believe that time is a companion who goes with us on the journey and reminds us to cherish every moment, because it will never come again. What we leave behind is not as important as how we've lived. After all Number One, we're only mortal.",author:"",source:"Star Trek",category:"movies",license:"Fair Use",difficulty:"hard",length:326},{id:"movies-055",text:"I must not fear. Fear is the mind killer. Fear is the little death that brings total obliteration. I will face my fear. I will permit it to pass over me and through me. And when my fear is gone I will turn and face fear's path, and only I will remain.",author:"",source:"Dune",category:"movies",license:"Fair Use",difficulty:"hard",length:251},{id:"movies-056",text:"I want adventure in the great wide somewhere. I want it more than I can tell. And for once it might be grand to have someone understand; I want so much more than they've got planned.",author:"",source:"Beauty and the Beast",category:"movies",license:"Fair Use",difficulty:"hard",length:182},{id:"movies-057",text:"If you're looking for the word that means caring about someone beyond all rationality and wanting them to have everything they want no matter how much it destroys you, it's love. And when you love someone you don't stop, ever. Even when people roll their eyes, and call you crazy. Even then. Especially then.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:308},{id:"movies-058",text:"You're missing the point. There's no throne, there is no version of this where you come out on top. Maybe your army comes and maybe it's too much for us, but it's all on you. Because if we can't protect the Earth, you can be damned well sure we'll avenge it.",author:"",source:"The Avengers",category:"movies",license:"Fair Use",difficulty:"hard",length:258},{id:"movies-059",text:"You're not a bad person. You are a very good person who bad things have happened to, you understand. Besides the world isn't split into good people and Death Eaters. We've all got both light, and dark inside of us, what matters is the part we choose to act on. That's who we really are.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:286},{id:"movies-060",text:"I wish that I was born a thousand years ago. I wish that I'd sailed the darkened seas on a great big clipper ship, going from this land to that in a sailor's suit and cap. Away from the big city where man cannot be free of all the evils of this town and of himself and those around.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:282},{id:"movies-061",text:"Baby, ever wondered why I could make you laugh and cry? Eclipsing all your summer skies, some things never change. And I need it more than love, and I love it more than life, and I want those stars above to shine this night.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:224},{id:"movies-062",text:"You think you're any different from me, or your friends, or this tree? If you listen hard enough, you can hear every living thing breathing together. You can feel everything growing. We're all living together, even if most folks don't act like it. We all have the same roots, and we are all branches of the same tree.",author:"",source:"Avatar",category:"movies",license:"Fair Use",difficulty:"hard",length:317},{id:"movies-063",text:"There can be no light without the dark, and so it is with magic. Myself, I always strive to live within the light. Is that what you told Tom Riddle, sir, when he came asking questions?",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:184},{id:"movies-064",text:"Well, the real reason that you've been sent over here is because they wanted you to be evaluated... to determine whether or not you are mentally ill. This is the real reason. Why do you think they might think that?",author:"",source:"One Flew Over the Cuckoo's Nest",category:"movies",license:"Fair Use",difficulty:"hard",length:214},{id:"movies-065",text:"It's so relieving to know that you're leaving as soon as you get paid. It's so relaxing to hear you're asking wherever you get your way. It's so soothing to know that you'll sue me, this is starting to sound the same. I miss the comfort in being sad.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:250},{id:"movies-066",text:"A hero can be anyone. Even a man doing something as simple and reassuring as putting a coat around a young boy's shoulders to let him know that the world hadn't ended.",author:"",source:"The Dark Knight",category:"movies",license:"Fair Use",difficulty:"hard",length:167},{id:"movies-067",text:"Even in the darkest times and places, there were always good people. People who would help others out of the kindness of their hearts.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:134},{id:"movies-068",text:"This combinatory play seems to be the essential feature in productive thought - before there is any connection with logical construction in words or other kinds of signs which can be communicated to others.",author:"",source:"Psycho",category:"movies",license:"Fair Use",difficulty:"hard",length:206},{id:"movies-069",text:"All I do is talk a big game, and make myself sound like a big shot, when I can't do anything! I never do anything, yet I complain like a pro. Who do you think I am? It's amazing that I can live like this and not feel ashamed!",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:225},{id:"movies-070",text:"I think you're still trying to figure out where you are. Where that ship of yours is. How to get back to that life.",author:"",source:"Star Trek",category:"movies",license:"Fair Use",difficulty:"medium",length:115},{id:"movies-071",text:"I had a dream. There was our world, and the world was dark because there weren't any robins, and the robins represented love. And for the longest time, there was this darkness. Then all of a sudden, thousands of robins were set free and they flew down and brought this blinding light of love. I guess it means that there is trouble until the robins come.",author:"",source:"Blue Velvet",category:"movies",license:"Fair Use",difficulty:"hard",length:354},{id:"movies-072",text:"Step out the front door like a ghost into the fog where no one notices the contrast of white on white. And in between the moon and you the angels get a better view of the crumbling difference between wrong and right. I walk in the air between the rain through myself and back again. Where? I don't know.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:303},{id:"movies-073",text:"It is a curious thing, Harry, but perhaps those who are best suited to power are those who have never sought it. Those who, like you, have leadership thrust upon them, and take up the mantle because they must, and find to their own surprise that they wear it well.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:264},{id:"movies-074",text:"Clear the lines of lint in your head one at a time and the king will be left standing alone like a guy on a street corner. Here, I'll make it easier for you.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:157},{id:"movies-075",text:"I have no idea to this day what those two Italian ladies were singing about. Truth is, I don't want to know. Some things are best left unsaid. I'd like to think they were singing about something so beautiful, it can't be expressed in words, and makes your heart ache because of it.",author:"",source:"The Shawshank Redemption",category:"movies",license:"Fair Use",difficulty:"hard",length:281},{id:"movies-076",text:"Men always believe that. With a law degree you're taking on insurance. After that you can do anything you want. You can work for me.",author:"",source:"The Godfather",category:"movies",license:"Fair Use",difficulty:"medium",length:132},{id:"movies-077",text:"Well, gentlemen, the way I see it, if this hot weather continues, it's going to melt the polar caps and the whole wide world. And all the parts that ain't water already will surely be flooded.",author:"",source:"Do the Right Thing",category:"movies",license:"Fair Use",difficulty:"hard",length:192},{id:"movies-078",text:"The terminator wouldn't stop, it would never leave him. It would never hurt him or shout at him or get drunk and hit him or say it was too busy to spend time with him. And it would die to protect him. Of all the would-be fathers that came over the years, this thing, this machine, was the only thing that measured up. In an insane world, it was the sanest choice.",author:"",source:"The Terminator",category:"movies",license:"Fair Use",difficulty:"hard",length:363},{id:"movies-079",text:"You must know that there is nothing higher and stronger and more wholesome and good for life in the future than some good memory, especially a memory of childhood, of home. People talk to you a great deal about your education, but some good, sacred memory, preserved from childhood, is perhaps the best education. If a man carries many such memories with him into life, he is safe to the end of his days, and if one has only one good memory left in one's heart, even that may sometime be the means of saving us.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:511},{id:"movies-080",text:"I'll tell you why. I think you're a lonely person. I drive by this place a lot and I see you here. I see a lot of people around you. And I see all these phones and all this stuff on your desk. It means nothing. Then when I came inside and I met you, I saw in your eyes and I saw the way you carried yourself that you're not a happy person. And I think you need something. And if you want to call it a friend, you can call it a friend.",author:"",source:"Taxi Driver",category:"movies",license:"Fair Use",difficulty:"hard",length:434},{id:"movies-081",text:"I would say he has quite a few problems. His energy seems to go in the wrong places. When I walked in and I saw you two sitting there, I could just tell by the way you were both relating that there was no connection whatsoever. And I felt when I walked in that there was something between us. There was an impulse that we were both following. So that gave me the right to come in and talk to you.",author:"",source:"Taxi Driver",category:"movies",license:"Fair Use",difficulty:"hard",length:396},{id:"movies-082",text:"Every second he breathed, the smell of the grass, the cool air on his face, was so precious: To think that people had years and years, time to waste, so much time it dragged, and he was clinging to each second.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:210},{id:"movies-083",text:"I do not see it. It is interesting that people try to find meaningful patterns in things that are essentially random. I have noticed that the images they perceive sometimes suggest what they are thinking about at that particular moment. Besides, it is clearly a bunny rabbit.",author:"",source:"Star Trek",category:"movies",license:"Fair Use",difficulty:"hard",length:275},{id:"movies-084",text:"I think you need something. And if you want to call it a friend, you can call it a friend.",author:"",source:"Taxi Driver",category:"movies",license:"Fair Use",difficulty:"medium",length:90},{id:"movies-085",text:"Well, the way they make shows is, they make one show. That show's called a pilot. Then they show that show to the people who make shows, and on the strength of that one show they decide if they're going to make more shows. Some pilots get picked and become television programs. Some don't, become nothing. She starred in one of the ones that became nothing.",author:"",source:"Pulp Fiction",category:"movies",license:"Fair Use",difficulty:"hard",length:357},{id:"movies-086",text:"If you're reading this, you've gotten out. And if you've come this far, maybe you're willing to come a little further. You remember the name of the town, don't you? I could use a good man to help me get my project on wheels. I'll keep an eye out for you and the chessboard ready. Remember, Red, hope is a good thing, maybe the best of things, and no good thing ever dies. I will be hoping that this letter finds you, and finds you well.",author:"",source:"The Shawshank Redemption",category:"movies",license:"Fair Use",difficulty:"hard",length:436},{id:"movies-087",text:"And I need it more than love, and I love it more than life, and I want those stars above to shine this night.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:109},{id:"movies-088",text:"Precious are the dead that lie there, every stone over them speaks of such burning life in the past, of such passionate faith in their work, their truth, their struggle and their science, that I know I shall fall on the ground and kiss those stones and weep over them; though I'm convinced in my heart that it's long been nothing but a graveyard.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:346},{id:"movies-089",text:"All the times that I've cried, keeping all the things I knew inside. And it's hard, but it's harder to ignore it. If they were right I'd agree, but it's them they know, not me. Now there's a way and I know that I have to go away.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:229},{id:"movies-090",text:"You're right, Will. I can't do this proof. But you can and when it comes to that it's only about... it's just a handful of people in the world who can tell the difference between you and me. But I'm one of them.",author:"",source:"Good Will Hunting",category:"movies",license:"Fair Use",difficulty:"hard",length:211},{id:"movies-091",text:"He was close, real close. I couldn't see him yet, but I could feel him, as if the boat were being sucked upriver and the water was flowing back into the jungle. Whatever was going to happen, it wasn't gonna be the way they call it back in Nha Trang.",author:"",source:"Apocalypse Now",category:"movies",license:"Fair Use",difficulty:"hard",length:249},{id:"movies-092",text:"Do you realize that more people will be watching you tonight than all those who have seen theater plays in the last forty years?",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:128},{id:"movies-093",text:"Above all, don't lie to yourself. The man who lies to himself and listens to his own lie comes to a point that he cannot distinguish the truth within him, or around him, and so loses all respect for himself and for others. And having no respect he ceases to love.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:263},{id:"movies-094",text:"I wonder, how you can expect to gain an idea of my usual teaching methods if you continue to interrupt me? You see, I do not generally permit people to talk when I am talking.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:175},{id:"movies-095",text:"No one really runs away from anything. It's like a private trap that holds us in like a prison. You know what I think? I think that we're all in our private traps, clamped in them, and none of us can ever get out. We scratch and we claw, but only at the air, only at each other, and for all of it, we never budge an inch.",author:"",source:"Psycho",category:"movies",license:"Fair Use",difficulty:"hard",length:321},{id:"movies-096",text:"This is what I offer each of you today: one tiny vial of liquid luck to the student who in the hour that remains manages to brew an acceptable draught of living death. The recipe for which can be found on page 10 of your books.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:227},{id:"movies-097",text:"I search the faces of the gods... for ways to please you, to make you proud. One kind word, one full hug... where you pressed me to your chest and held me tight. Would have been like the sun on my heart for a thousand years. What is it in me that you hate so much?",author:"",source:"Gladiator",category:"movies",license:"Fair Use",difficulty:"hard",length:264},{id:"movies-098",text:"I hate this place, this zoo, this prison, this reality, whatever you want to call it. I can't stand it any longer. It's the smell, if there is such a thing. I feel saturated by it. I can taste your stink, and every time I do, I fear that I've somehow been infected by it.",author:"",source:"The Matrix",category:"movies",license:"Fair Use",difficulty:"hard",length:271},{id:"movies-099",text:"I know more about the private lives of celebrities than I do about any governmental policy that will actually affect me. I'm interested in things that are none of my business, and I'm bored by things that are important to know.",author:"",source:"Psycho",category:"movies",license:"Fair Use",difficulty:"hard",length:227},{id:"movies-100",text:"The man who lies to himself and listens to his own lie comes to such a pass that he cannot distinguish the truth within him, or around him, and so loses all respect for himself and for others. And having no respect he ceases to love, and in order to occupy and distract himself without love he gives way to passions and coarse pleasures, and sinks to bestiality in his vices, all from continual lying to other men and to himself.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:429},{id:"movies-101",text:"Have you ever fixed a nose before? No, but I've done several toes, and how different are they really?",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"medium",length:101},{id:"movies-102",text:"I know you have received orders from our commandant, which he has received from his superiors, to dispose of the population of this camp. Now would be the time to do it. Here they are; they're all here. This is your opportunity. Or, you could leave, and return to your families as men instead of murderers.",author:"",source:"Schindler's List",category:"movies",license:"Fair Use",difficulty:"hard",length:306},{id:"movies-103",text:"He pushes people away before they get a chance to leave him. It's a defense mechanism. And for twenty years he's been alone because of that. And if you push him right now, it's gonna be the same thing all over again and I'm not gonna let that happen to him.",author:"",source:"Good Will Hunting",category:"movies",license:"Fair Use",difficulty:"hard",length:257},{id:"movies-104",text:"Let me tell you why you're here. You're here because you know something. What you know you can't explain, but you feel it. You've felt it your entire life, that there's something wrong with the world. You don't know what it is, but it's there, like a splinter in your mind, driving you mad. It is this feeling that has brought you to me. Do you know what I'm talking about?",author:"",source:"The Matrix",category:"movies",license:"Fair Use",difficulty:"hard",length:373},{id:"movies-105",text:"The breath of the morning, I keep forgetting the smell of the warm summer air. I live in a town where you can't smell a thing; you watch your feet for cracks in the pavement. Up above, aliens hover making home movies for the folks back home, of all these weird creatures who lock up their spirits, drill holes in themselves and live for their secrets...",author:"",source:"Alien",category:"movies",license:"Fair Use",difficulty:"hard",length:353},{id:"movies-106",text:"The days go on and on... they don't end. All my life needed was a sense of someplace to go. I don't believe that one should devote his life to morbid self-attention. I believe that one should become a person like other people.",author:"",source:"Taxi Driver",category:"movies",license:"Fair Use",difficulty:"hard",length:226},{id:"movies-107",text:"You don't care about anything except you. You just want to persuade people that you love 'em so much that they ought to love you back. Only you want love on your own terms. Something to be played your way, according to your rules.",author:"",source:"Citizen Kane",category:"movies",license:"Fair Use",difficulty:"hard",length:230},{id:"movies-108",text:"Source routing is a way of moving a packet through a network in which the path is predetermined by the source or some device that tells the source about the path. The path information is placed in the packet. When the packet arrives at a switching device, no forwarding decision is necessary. The device looks at the path information in the packet to determine the port on which it should forward the packet.",author:"",source:"Network",category:"movies",license:"Fair Use",difficulty:"hard",length:408},{id:"movies-109",text:"As much money and life as you could want! The two things most human beings would choose above all - the trouble is, humans do have a knack of choosing precisely those things that are worst for them.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:198},{id:"movies-110",text:"You, me, or nobody is gonna hit as hard as life. But it ain't about how hard you hit. It's about how hard you can get hit and keep moving forward. That's how winning is done!",author:"",source:"Rocky",category:"movies",license:"Fair Use",difficulty:"hard",length:174},{id:"movies-111",text:"Ever since your brother got taken down... I've had my eye on you. Because all that building resentment was written over your face. I know that when I see it. And I know just how much grudges like that... can cloud a person's vision.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:232},{id:"movies-112",text:"If you're willing to go through the battling to get to where you wanna get, who's got the right to stop you? Maybe you guys got something you never finished, something you really wanna do, something you never said to somebody - something! And you're told no, even after you pay your dues. Who's got the right to tell you that? Who? Nobody!",author:"",source:"Rocky",category:"movies",license:"Fair Use",difficulty:"hard",length:339},{id:"movies-113",text:"You look in excellent health to me, Potter, so you will excuse me if I don't let you off homework today. I assure you that if you do die, you need not hand it in.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:162},{id:"movies-114",text:"Some day, and that day may never come, I will call upon you to do a service for me. But until that day, consider this justice a gift on my daughter's wedding day.",author:"",source:"The Godfather",category:"movies",license:"Fair Use",difficulty:"hard",length:162},{id:"movies-115",text:"It makes no difference, it don't make any difference to me what a man does for a living, you understand. But your business is a little dangerous.",author:"",source:"The Godfather",category:"movies",license:"Fair Use",difficulty:"medium",length:145},{id:"movies-116",text:"Sometimes it makes me sad, though... Andy being gone. I have to remind myself that some birds aren't meant to be caged. Their feathers are just too bright. And when they fly away, the part of you that knows it was a sin to lock them up DOES rejoice. But still, the place you live in is that much more drab and empty that they're gone. I guess I just miss my friend.",author:"",source:"The Shawshank Redemption",category:"movies",license:"Fair Use",difficulty:"hard",length:365},{id:"movies-117",text:"It was one of those days when it's a minute away from snowing and there's this electricity in the air, you can almost hear it. And this bag was, like, dancing with me. Like a little kid begging me to play with it. For fifteen minutes. And that's the day I knew there was this entire life behind things, and this incredibly benevolent force.",author:"",source:"American Beauty",category:"movies",license:"Fair Use",difficulty:"hard",length:340},{id:"movies-118",text:"And his dad's smile faded just a bit - the prodigy could read, but he could not see. And if only Colin had known that he was missing a piece, that his inability to see himself in the story of a circle was an unfixable problem, he might have known that the rest of the world would catch up with him as time passed.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:313},{id:"movies-119",text:"I'm in deep with this girl but she's out of her mind. We all need something to live for.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:88},{id:"movies-120",text:"I think you're gonna find - when all this stuff is over and done - I think you're gonna find yourself one smiling guy. Thing is, Butch, right now you got ability. But painful as it may be, ability don't last. Now that's a hard fact of life, but it's a fact of life you're gonna have to get realistic about.",author:"",source:"Pulp Fiction",category:"movies",license:"Fair Use",difficulty:"hard",length:306},{id:"movies-121",text:"Life can get pretty crazy at times. It can be hectic, confusing, stressful, and that's on a good day. Life can be full of happiness and full of sadness. One moment you're on top of the world and nothing can go wrong. The next, it feels as if nothing will ever be right again. I guess it depends where you are right now on your ride through life whether you smile when you read this or fight back tears.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:402},{id:"movies-122",text:"If you feel yourself hitting up against your limit, remember for what cause you clench your fists... remember why you started down this path, and let that memory carry you beyond your limit.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:190},{id:"movies-123",text:"The rest of my attention is back at the offices of Facebook, where my colleagues and I are doing things that no one in this room, including and especially your clients, are intellectually or creatively capable of doing.",author:"",source:"Network",category:"movies",license:"Fair Use",difficulty:"hard",length:219},{id:"movies-124",text:"This is your last chance. After this there is no turning back. You take the blue pill: the story ends, you wake up in your bed and believe whatever you want to believe. You take the red pill: you stay in Wonderland, and I show you how deep the rabbit hole goes. Remember, all I'm offering is the truth, nothing more.",author:"",source:"The Matrix",category:"movies",license:"Fair Use",difficulty:"hard",length:316},{id:"movies-125",text:"What is it about owning things? Why do we feel the need to own what we love and why do we become such jerks when we do? We've all been there, you know: we want something; we own it; and by owning it we change it. When you finally win that girl of your dreams, the first thing you do is try to change her. That little thing she does with her hair, the way she wears her clothes, the way she chews her gum. Until eventually, what you like, what you don't like, and what you change all merges into one. Like a watercolor in the rain.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:530},{id:"movies-126",text:"Here he was writing a formula the accuracy of which was certain, but whose origin in his brain and way of discovery he did not explain and we could not guess.",author:"",source:"Psycho",category:"movies",license:"Fair Use",difficulty:"hard",length:158},{id:"movies-127",text:`So I want you to get up now. I want all of you to get up out of your chairs. I want you to get up right now and go to the window. Open it and stick your head out and yell, "I'm as mad as hell and I'm not going to take this anymore!"`,author:"",source:"Network",category:"movies",license:"Fair Use",difficulty:"hard",length:232},{id:"movies-128",text:"You think the dead we loved ever truly leave us? You think that we don't recall them more clearly than ever in times of great trouble? Your father is alive in you, Harry, and shows himself plainly when you have need of him.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:223},{id:"movies-129",text:"These mist-covered mountains are a home now for me, but my home is the lowlands and always will be. Someday you'll return to your valleys and your farms and you'll no longer burn to be brothers in arms.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:202},{id:"movies-130",text:'And when he came to the place where the wild things are, they roared their terrible roars and gnashed their terrible teeth and rolled their terrible eyes and showed their terrible claws till Max said "Be still!" And tamed them with the magic trick of staring into all their yellow eyes without blinking once. And they were frightened and called him the most wild thing of all, and made him king of all wild things.',author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:414},{id:"movies-131",text:"He's better at this than I've ever been at anything in my life. He's better at this than you'll ever be at anything. My son has a gift. He has a gift and when you acknowledge that then maybe we will have something to talk about.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:228},{id:"movies-132",text:"The unknown future rolls toward us. I face it for the first time with a sense of hope, because if a machine, a Terminator, can learn the value of human life, maybe we can, too.",author:"",source:"The Terminator",category:"movies",license:"Fair Use",difficulty:"hard",length:176},{id:"movies-133",text:"We've known each other for many years but this is the first time you've ever come to me for counsel or for help. I can't remember the last time you invited me to your house for a cup of coffee, even though my wife is the Godmother to your only child. But, let's be frank here. You never wanted my friendship and you were afraid to be in my debt.",author:"",source:"The Godfather",category:"movies",license:"Fair Use",difficulty:"hard",length:345},{id:"movies-134",text:"There's something waiting in the stratosphere, and it's waiting just to tell us what it's doing here.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:101},{id:"movies-135",text:"For attractive lips, speak words of kindness. For lovely eyes, seek out the good in people. For a slim figure, share your food with the hungry. For beautiful hair, let a child run his or her fingers through it once a day. For poise, walk with the knowledge that you never walk alone...",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:285},{id:"movies-136",text:"What is your obsession with this money? My father died when I was thirteen and I inherited this money. You don't think that every day I wake up and wish I could give it back? That I would give it back in a second if I could have one more day with him? But I can't, and that's my life and I deal with it.",author:"",source:"Good Will Hunting",category:"movies",license:"Fair Use",difficulty:"hard",length:303},{id:"movies-137",text:"But physical interpretation, which is in general a very sure guide and had been most often such for me, misled me in that case.",author:"",source:"Psycho",category:"movies",license:"Fair Use",difficulty:"medium",length:127},{id:"movies-138",text:"Stand tall, boy. Have some respect for yourself. Don't you know if you let people walk over you now they'll be walking over you for the rest of your life! Look at me. You think I'm gonna spend the rest of my life in this slop house?",author:"",source:"Back to the Future",category:"movies",license:"Fair Use",difficulty:"hard",length:232},{id:"movies-139",text:"One day soon, man is going to be able to harness incredible energies, maybe even the atom... energies that could ultimately hurl us to other worlds in... in some sort of spaceship. And the men that reach out into space will be able to find ways to feed the hungry millions of the world and to cure their diseases. They will be able to find a way to give each man hope and a common future. And those are the days worth living for.",author:"",source:"Star Trek",category:"movies",license:"Fair Use",difficulty:"hard",length:429},{id:"movies-140",text:"Take care where you're going, doing all the things you do. Even when you're away from me, I'm the closest thing to you. Come here when it's over, when you think you've lost your world. Come here with your restlessness, and I will calm you down. 'Cause it feels like home when you are here.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:289},{id:"movies-141",text:"We sat and drank with the sun on our shoulders and felt like free men. Hell, we could have been tarring the roof of one of our own houses. We were the lords of all creation. As for Andy - he spent that break hunkered in the shade, a strange little smile on his face, watching us drink his beer.",author:"",source:"The Shawshank Redemption",category:"movies",license:"Fair Use",difficulty:"hard",length:294},{id:"movies-142",text:"To be my own master. Such a thing would be greater than all the magic and all the treasures in all the world! But what am I talking about? Let's get real here, it's not gonna happen. Genie, wake up and smell the hummus.",author:"",source:"Aladdin",category:"movies",license:"Fair Use",difficulty:"hard",length:219},{id:"movies-143",text:"If you know what you're worth, go and get what you're worth. But you gotta be willing to take the hits, and not pointing fingers... saying you ain't where you wanna be because of him or her or anybody! Cowards do that, and that ain't you! You're better than that!",author:"",source:"Rocky",category:"movies",license:"Fair Use",difficulty:"hard",length:263},{id:"movies-144",text:"People talk to you a great deal about your education, but some good memory is perhaps the best education.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:105},{id:"movies-145",text:"They are important, you understand, without being interesting. Indeed, I have found that it is usually in unimportant matters that there is a field for the observation, and for the quick analysis of cause and effect which gives the charm to an investigation. The larger crimes are apt to be the simpler, for the bigger the crime the more obvious, as a rule, is the motive.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:372},{id:"movies-146",text:"Happiness can be found, even in the darkest of times, if one only remembers to turn on the light.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"medium",length:97},{id:"movies-147",text:"Maybe you should come with me for a few weeks. See what happens. See how much you learn. Then, we'll talk about your future.",author:"",source:"The Godfather",category:"movies",license:"Fair Use",difficulty:"medium",length:124},{id:"movies-148",text:"I think you're a lonely person. I see all these phones and all this stuff on your desk. It means nothing.",author:"",source:"Taxi Driver",category:"movies",license:"Fair Use",difficulty:"medium",length:105},{id:"movies-149",text:"I believe that for every one of these anxious, anguished people who have come here this evening there must be hundreds of others also touched by the implanted vision who never made it this far. It's simply because they never watched the television. Or perhaps they watched it but never made the psychic connection.",author:"",source:"Close Encounters of the Third Kind",category:"movies",license:"Fair Use",difficulty:"hard",length:314},{id:"movies-150",text:"Of all the gin joints in all the towns in all the world, she walks into mine.",author:"",source:"Casablanca",category:"movies",license:"Fair Use",difficulty:"easy",length:77},{id:"movies-151",text:"Look, I understand too little too late. I realize there are things you say and do you can never take back. But what would you be if you didn't even try? You have to try. So after a lot of thought, I'd like to reconsider. Please, if it's not too late, make it a cheeseburger.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:274},{id:"movies-152",text:"I tried several times to call her, but after the first call, she wouldn't come to the phone any longer. I also sent flowers but with no luck. The smell of the flowers only made me sicker. The headaches got worse. I think I got stomach cancer. I shouldn't complain though. You're only as healthy as you feel.",author:"",source:"Taxi Driver",category:"movies",license:"Fair Use",difficulty:"hard",length:307},{id:"movies-153",text:`Dolores Umbridge stated with bureaucratic certainty, "The Ministry believes theoretical knowledge suffices for examinations, the essence of education." Harry Potter challenged, "How does theory prepare us for the real threats?" Umbridge scoffed, "There's nothing 'out there.' Who'd harm children like you?" Harry quipped, "Maybe someone named Lord Voldemort."`,author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:359},{id:"movies-154",text:"Even a few people leaving would reverberate through the entire user base. The users are interconnected; that is the whole point. College kids are online because their friends are online, and if one domino goes, the other dominoes go. Don't you get that?",author:"",source:"Network",category:"movies",license:"Fair Use",difficulty:"hard",length:253},{id:"movies-155",text:"The road is long with many a winding turn that leads us to who knows where. But I'm strong, strong enough to carry him. He ain't heavy, he's my brother.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:152},{id:"movies-156",text:"Very often research which has deeply interested me while I was investigating it loses its interest for me just after I have the solution, unhappily at a time which coincides with the period when I have to record it. After a while, say a couple of months, I come to a more just appreciation of it.",author:"",source:"Psycho",category:"movies",license:"Fair Use",difficulty:"hard",length:296},{id:"movies-157",text:"I called Betsy again at her office and she said maybe we'd go to a movie together after she gets off work tomorrow. That's my day off. At first she hesitated but I called her again and then she agreed.",author:"",source:"Taxi Driver",category:"movies",license:"Fair Use",difficulty:"hard",length:201},{id:"movies-158",text:"Something inside me has always been there. But now it's awake. And I don't know what it is or where it came from, but I need help.",author:"",source:"Star Wars",category:"movies",license:"Fair Use",difficulty:"medium",length:130},{id:"movies-159",text:"It's not time to make a change. Just sit down and take it slowly. You're still young, that's your fault, there's so much you have to go through. Find a girl, settle down. If you want, you can marry. Look at me, I am old, but I'm happy.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:235},{id:"movies-160",text:"There she goes. There she goes again, racing through my brain. And I just can't contain this feeling that remains.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:114},{id:"movies-161",text:"The world ain't all sunshine and rainbows. It's a very mean and nasty place and I don't care how tough you are, it will beat you to your knees and keep you there permanently if you let it. You, me, or nobody is gonna hit as hard as life. But it ain't about how hard you hit. It's about how hard you can get hit and keep moving forward. How much you can take and keep moving forward. That's how winning is done! Now if you know what you're worth then go out and get what you're worth. But you've gotta be willing to take the hits, and not pointing fingers saying you ain't where you wanna be because of him, or her, or anybody! Cowards do that and that ain't you! You're better than that!",author:"",source:"Rocky",category:"movies",license:"Fair Use",difficulty:"hard",length:687},{id:"movies-162",text:"If I'm curt with you it's because time is a factor. I think fast, I talk fast and I need you guys to act fast if you wanna get out of this. So, pretty please with sugar on top. Clean the car!",author:"",source:"Pulp Fiction",category:"movies",license:"Fair Use",difficulty:"hard",length:191},{id:"movies-163",text:"There's not a day goes by I don't feel regret. Not because I'm in here, because you think I should. I look back on the way I was then: a young, stupid kid who committed that terrible crime. I want to talk to him. I want to try to talk some sense to him, tell him the way things are. But I can't. That kid's long gone, and this old man is all that's left. I got to live with that.",author:"",source:"The Shawshank Redemption",category:"movies",license:"Fair Use",difficulty:"hard",length:379},{id:"movies-164",text:"What is finished is the idea that this great country is dedicated to the freedom and flourishing of every individual in it. It's the individual that's finished. It's the single, solitary human being that's finished. It's every single one of you out there that's finished, because this is no longer a nation of independent individuals.",author:"",source:"Network",category:"movies",license:"Fair Use",difficulty:"hard",length:334},{id:"movies-165",text:"What is the point of being alive if you don't at least try to do something remarkable?",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:86},{id:"movies-166",text:"There is no good and evil, there is only power and those too weak to seek it.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"easy",length:77},{id:"movies-167",text:"I've thought about this a lot. If we're together this is what's going to happen. I'm going to keep pursuing what I'm pursuing, and it's going to take up more and more of my time. You're going to see me less and less. When you do, I'll be distracted, I'll be upset, I'll be playing things in my mind. And you're going to just grow to resent me. At a certain point, you'll tell me to ease up on the drumming, to spend more time with you. And I won't be able to. And I'll start to resent you for even asking me that. I'll feel like you're dragging me down, you'll feel like you don't matter - and before long, we'll hate each other. So I think we should just cut it off now, cleanly, for those reasons.",author:"",source:"Whiplash",category:"movies",license:"Fair Use",difficulty:"hard",length:699},{id:"movies-168",text:"There's no such thing as a painless lesson, they just don't exist. Sacrifices are necessary. You can't gain anything without losing something first. Although if you can endure that pain and walk away from it, you'll find that you now have a heart strong enough to overcome any obstacle. Yeah... a heart made fullmetal.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:318},{id:"movies-169",text:"He rode past me and kept on goin'. Never said nothin' goin' by. He just rode on past and he had his blanket wrapped around him and his head down. And when he rode past I seen he was carryin' fire in a horn the way people used to do and I could see the horn from the light inside of it. About the color of the moon. And in the dream I knew that he was goin' on ahead and that he was fixin' to make a fire somewhere out there in all that dark and all that cold, and I knew that whenever I got there he would be there. Out there up ahead.",author:"",source:"No Country for Old Men",category:"movies",license:"Fair Use",difficulty:"hard",length:535},{id:"movies-170",text:"You've been confusing since the day I met you. Another night chasing, this feels like home. Since I've been miles away, no change. Outsider inside looking dazed. Just wash the glitter off your face and go home.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:210},{id:"movies-171",text:"I think if your clients want to sit on my shoulders and call themselves tall, they have the right to give it a try. But there's no requirement that I enjoy sitting here listening to people lie. You have part of my attention. You have the minimum amount. The rest of my attention is back at the offices of Facebook, where my colleagues and I are doing things that no one in this room, including and especially your clients, are intellectually or creatively capable of doing.",author:"",source:"Network",category:"movies",license:"Fair Use",difficulty:"hard",length:473},{id:"movies-172",text:"On the contrary, it may happen that the atoms are launched in a rather disorderly manner. If so, most of the meetings will be uninteresting ones; but on the other hand, as in a kind of lottery, that disorder can be highly valuable, because the few meetings which are useful, being of an exceptional nature and between seemingly very remote ideas, will probably be the most important ones.",author:"",source:"Psycho",category:"movies",license:"Fair Use",difficulty:"hard",length:388},{id:"movies-173",text:"You're telling us you killed those three young men on the subway? And why should we believe you? I've got nothing left to lose, nothing can hurt me anymore. My life, is nothing but a comedy. Let me get this straight, you think killing those guys is funny. I do, and I'm tired of pretending it's not. Comedy is subjective Murray, isn't that what they say. All of you, this system that knows so much, you decide what's right or wrong. The same way that you decide what's funny, or not.",author:"",source:"Joker",category:"movies",license:"Fair Use",difficulty:"hard",length:483},{id:"movies-174",text:"In one small part of space, the war continues. In war, there can be only one victor. Space is an uninhabited wilderness and bloody wounds disappear with time. Maybe the multitude of stars in the sky remember those wounds. Maybe it is fated that even those stars will vanish one day. Man's presence in the midst of these stars is all that remains of a forgotten battle.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:368},{id:"movies-175",text:"If this had been an old house, with creaking wood, and dark shadows, and heavily panelled walls, there might have been an eerie feeling. But this house was the essence of modernity. There were no dark corners - no possible sliding panels - it was flooded with electric light - everything was new and bright and shining. There was nothing hidden in this house, nothing concealed. It had no atmosphere about it. Somehow, that was the most frightening thing of all...",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:464},{id:"movies-176",text:"I hadn't seen anything so beautiful in my life. She was like an angel. I just sat next to her on that bus and had a conversation all the way to school. Next to Mamma no one ever talked to me or asked me questions. From that day on we were always together. Jenny, she helped me learn how to read and I showed her how to swing. Sometimes we'd just sit out and wait for the stars. For some reason Jenny never wanted to go home. She was my most special friend, my only friend.",author:"",source:"Forrest Gump",category:"movies",license:"Fair Use",difficulty:"hard",length:472},{id:"movies-177",text:"If there is a design or pattern on our china, we eat until we can see the design clearly. If you're on a diet, eat from plates with no design - or even better, from plain white china. Without the design present to influence you, you have less incentive to clean your plate.",author:"",source:"Psycho",category:"movies",license:"Fair Use",difficulty:"hard",length:273},{id:"movies-178",text:"Man, do not pride yourself on your superiority to the animals, for they are without sin, while you, with all your greatness, you defile the earth wherever you appear and leave an ignoble trail behind you - and that is true, alas, for almost every one of us!",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:257},{id:"movies-179",text:"If one has only one good memory left in one's heart, that may sometimes be the means of saving us.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:98},{id:"movies-180",text:"They told me that you had gone totally insane, and that your methods were unsound.",author:"",source:"Apocalypse Now",category:"movies",license:"Fair Use",difficulty:"medium",length:82},{id:"movies-181",text:"See, I write jokes for a living, man. You know, I sit in my hotel at night, I think of something that's funny, then I go get a pen and I write it down. Or, if the pen's too far away, I have to convince myself that what I thought of ain't funny.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:244},{id:"movies-182",text:"Every temptation is an opportunity to do good. On the path to spiritual maturity, even temptation becomes a stepping-stone rather than a stumbling block when you realize that it is just as much an occasion to do the right thing as it is to do the wrong thing. Temptation simply provides the choice.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:298},{id:"movies-183",text:"Combat for a naval aviator is fought in short, violent bursts. Our missions last but an hour or two before we are clear of danger and back on the carrier playing poker with our buddies. We are spared the sustained misery of the infantrymen who slog through awful conditions and danger for months on end.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:303},{id:"movies-184",text:"Whatever happened to the values of humanity? Whatever happened to the fairness and equality? Instead of spreading love we're spreading animosity, lack of understanding leading us away from unity. That's the reason why sometimes I'm feeling under, that's the reason why sometimes I'm feeling down.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:296},{id:"movies-185",text:"This tree is our symbol. Our affirmation of life, and everyone in this town gives part of their water rations to keep it alive. We've learned, administrator, that hope is a powerful weapon against anything, even drought.",author:"",source:"Star Trek",category:"movies",license:"Fair Use",difficulty:"hard",length:220},{id:"movies-186",text:"From the tip of his wand burst the silver doe. She landed on the office floor, bounded once across the office, and soared out of the window. Dumbledore watched her fly away, and as her silvery glow faded he turned back to Snape, and his eyes were full of tears.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:261},{id:"movies-187",text:"Every day I come by your house and I pick you up. And we go out. We have a few drinks, and a few laughs, and it's great. But you know what the best part of my day is? For about ten seconds, from when I pull up to the curb and when I get to your door, 'cause I think, maybe I'll get up there and I'll knock on the door and you won't be there. No goodbye. No see you later. No nothing. You just left. I don't know much, but I know that.",author:"",source:"Good Will Hunting",category:"movies",license:"Fair Use",difficulty:"hard",length:434},{id:"movies-188",text:"Well, you've cracked the sky, scrapers fill the air, but will you keep on building higher till there's no more room up there? Will you make us laugh, will you make us cry? Will you tell us when to live, will you tell us when to die?",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:232},{id:"movies-189",text:"You were the chosen one! It was said that you would destroy the Sith, not join them. Bring balance to the Force, not leave it in darkness.",author:"",source:"Star Wars",category:"movies",license:"Fair Use",difficulty:"medium",length:138},{id:"movies-190",text:`Listen, where I'm from there's a saying, "Three heads are better than one." Wait, is it two heads? Whatever, the point is, three heads, thinking together are harder to break than only one arrow. It means you should rely on those around you instead of thinking about stuff alone!`,author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:278},{id:"movies-191",text:"I have something here for you. Your father wanted you to have this when you were old enough, but your uncle wouldn't allow it. He feared you might follow old Obi-Wan on some damn fool idealistic crusade like your father did.",author:"",source:"Star Wars",category:"movies",license:"Fair Use",difficulty:"hard",length:224},{id:"movies-192",text:"As Harry and Ron walked back to the castle for dinner, their pockets weighed down with rock cakes they'd been too polite to refuse, Harry thought that none of the lessons he'd had so far had given him as much to think about as tea with Hagrid.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:243},{id:"movies-193",text:"My pop was real big. He did like he pleased. That's why everybody worked on him. The last time I seen my father, he was blind and diseased from drinking. And every time he put the bottle to his mouth, he didn't suck out of it, it sucked out of him until he shrunk so wrinkled and yellow even the dogs didn't know him.",author:"",source:"One Flew Over the Cuckoo's Nest",category:"movies",license:"Fair Use",difficulty:"hard",length:317},{id:"movies-194",text:"I said that I would see you because I had heard that you were a serious man. A man to be treated with respect but I must say no to you and I will give you my reasons. It's true, I have a lot of friends in politics. But they wouldn't be so friendly if they knew my business was drugs instead of gambling which they consider a harmless vice, but drugs, that's a dirty business.",author:"",source:"The Godfather",category:"movies",license:"Fair Use",difficulty:"hard",length:375},{id:"movies-195",text:"My aunt used to live in Paris. I remember, she used to come home and she would tell us stories about being abroad, and I remember she told us she jumped into the river once. Barefoot. She smiled. Leapt without looking, and tumbled into the Seine. The water was freezing, she spent a month sneezing, but said she would do it again.",author:"",source:"La La Land",category:"movies",license:"Fair Use",difficulty:"hard",length:330},{id:"movies-196",text:"I don't know why he saved my life. Maybe in those last moments he loved life more than he ever had before. Not just his life, anybody's life, my life. All he'd wanted were the same answers the rest of us want. Where did I come from? Where am I going? How long have I got?",author:"",source:"Blade Runner",category:"movies",license:"Fair Use",difficulty:"hard",length:271},{id:"movies-197",text:"It is by will alone I set my mind in motion. It is by the juice of Sapho that thoughts acquire speed, the lips acquire stains, the stains become a warning. It is by will alone I set my mind in motion.",author:"",source:"Dune",category:"movies",license:"Fair Use",difficulty:"hard",length:200},{id:"movies-198",text:"Some people can't believe in themselves until someone else believes in them first.",author:"",source:"Good Will Hunting",category:"movies",license:"Fair Use",difficulty:"medium",length:82},{id:"movies-199",text:"The Sky People have sent us a message that they can take whatever they want. That no one can stop them. Well, we will send them a message. You ride out as fast as the wind can carry you. You tell the other clans to come. Tell them Toruk Makto calls to them!",author:"",source:"Avatar",category:"movies",license:"Fair Use",difficulty:"hard",length:257},{id:"movies-200",text:"Brother, I'm not depressed and haven't lost spirit. Life everywhere is life, life is in ourselves and not in the external. There will be people near me, and to be a human being among human beings, and remain one forever, no matter what misfortunes befall, not to become depressed, and not to falter - this is what life is, herein lies its task.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:344},{id:"movies-201",text:"If there is one thing the history of evolution has taught us it's that life will not be contained. Life breaks free, expands to new territory, and crashes through barriers, painfully, maybe even dangerously.",author:"",source:"Jurassic Park",category:"movies",license:"Fair Use",difficulty:"hard",length:207},{id:"movies-202",text:"I know you're into banks and Wall Street, but everyone knows you're the final word, you're like the Supreme Court. All I want to do is protect you from these guys and your lawyers can't do that.",author:"",source:"The Godfather",category:"movies",license:"Fair Use",difficulty:"hard",length:194},{id:"movies-203",text:"They used to tell me I was building a dream, and so I followed the mob. When there was earth to plow or guns to bear, I was always there, right on the job. They used to tell me I was building a dream with peace and glory ahead. Why should I be standing in line just waiting for bread? Once I built a railroad, I made it run. Made it race against time. Once I built a railroad, now it's done. Brother, can you spare a dime?",author:"Brother",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:422},{id:"movies-204",text:"A man who doesn't spend time with his family can never be a real man.",author:"",source:"The Godfather",category:"movies",license:"Fair Use",difficulty:"easy",length:69},{id:"movies-205",text:"I didn't know the girl, but I knew her family. All their lives were shattered in a nightmare of brutality. They try to carry on, try to bear the agony; try to hold some faith in the goodness of humanity.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:203},{id:"movies-206",text:`With your feet on the air and your head on the ground, try this trick and spin it, yeah. Your head will collapse, but there's nothing in it, and you'll ask yourself "Where is my mind?"`,author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:184},{id:"movies-207",text:"I just have a little question here. You could be a janitor anywhere. Why did you work at the most prestigious technical college in the whole world? And why did you sneak around at night and finish other people's formulas that only one or two people in the world could do and then lie about it? 'Cause I don't see a lot of honor in that, Will.",author:"",source:"Good Will Hunting",category:"movies",license:"Fair Use",difficulty:"hard",length:342},{id:"movies-208",text:"I have been told of a certain sea snake which has a very unusual method of attracting its prey. It will lie at the bottom of the ocean as if wounded. Then its enemies will approach, and yet it will lie quite still. And then its enemies will take little bites of it, and yet it remains still.",author:"",source:"Gladiator",category:"movies",license:"Fair Use",difficulty:"hard",length:291},{id:"movies-209",text:"You've undoubtedly noticed how some authors go to so much trouble to build up great tension a few pages before the end of their stories - but a reader who is holding the book physically in his hands can feel that the story is about to end. Hence, he has some extra information which acts as an advance warning, in a way.",author:"Gödel",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:320},{id:"movies-210",text:"It is the quality of one's convictions that determines one's success, not the number of followers.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"medium",length:98},{id:"movies-211",text:"No, get out of town. My mom thinks I'm going camping with the guys. Look, Jennifer, my mother would freak out if she knew I was going out with you and I'd get the standard lecture about how she never did that kind of stuff when she was a kid. I mean, look, I think the woman was born a nun.",author:"",source:"Back to the Future",category:"movies",license:"Fair Use",difficulty:"hard",length:290},{id:"movies-212",text:"Even there, in the mines, underground, I may find a human heart in another convict or murderer by my side. And I may make friends with him, for even there one may live and love and suffer. One may thaw and revive a frozen heart in that convict, one may wait upon him for years, and at last bring up from the dark depths a lofty soul, a feeling, suffering creature; one may bring forth an angel, create a hero!",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:409},{id:"movies-213",text:"Through these fields of destruction, baptisms of fire, I've witnessed your suffering as the battle raged higher. And though they did hurt me so bad in the fear and alarm you did not desert me, my brothers in arms.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:213},{id:"movies-214",text:"Come on, kid, don't fool around. Just let your hand drop to your side and the gun slip out. Everyone will still think you've got it. They're gonna be staring at your face, Mike. So walk out of the place real fast, but you don't run. Don't look nobody directly in the eye, but don't look away either. They're gonna be scared of you, believe me, so don't worry about nothing.",author:"",source:"The Godfather",category:"movies",license:"Fair Use",difficulty:"hard",length:373},{id:"movies-215",text:"Some pilots like the excitement of our missions, knowing that they are of short duration, but most of us concentrate so fiercely on finding our targets and avoiding calamity that we recall more vividly our relief when it's over than we do our exhilaration while it's going on.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:276},{id:"movies-216",text:"My brother, your father, he and I. Opposites. But I never doubted his love. He would do anything for me. But his temper clouded his judgment. I don't want to see the same thing happen to you.",author:"",source:"The Godfather",category:"movies",license:"Fair Use",difficulty:"hard",length:191},{id:"movies-217",text:"I saw in your eyes, and I saw the way you carried yourself that you're not a happy person.",author:"",source:"Taxi Driver",category:"movies",license:"Fair Use",difficulty:"medium",length:90},{id:"movies-218",text:"If I'm at a party where I'm not enjoying myself, I will put some cookies in my jacket pocket and leave without saying goodbye.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:126},{id:"movies-219",text:"I'd ask you about love, you'd probably quote me a sonnet. But you've never looked at a woman and been totally vulnerable. Known someone that could level you with her eyes, feeling like God put an angel on Earth just for you.",author:"",source:"Good Will Hunting",category:"movies",license:"Fair Use",difficulty:"hard",length:224},{id:"movies-220",text:"You're gonna blame me because you were the business head of the company and you made a bad business deal with your own company?",author:"",source:"Network",category:"movies",license:"Fair Use",difficulty:"medium",length:127},{id:"movies-221",text:"It is a capital mistake to theorize before one has data. Insensibly one begins to twist facts to suit theories, instead of theories to suit facts.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:146},{id:"movies-222",text:"Your mother died to save you. If there is one thing Voldemort cannot understand, it is love. He didn't realize love as powerful as your mother's love for you leaves its own mark. Not a scar, no visible sign... to have been loved so deeply, even though the person who loved us is gone, will give us some protection forever. It is in your very skin. Quirrell, full of hatred, greed and ambition, sharing his soul with Voldemort, could not touch you for this reason. It was agony to touch a person marked by something so good.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:523},{id:"movies-223",text:"They're called Thestrals, they're quite gentle really. But people avoid them because they're a bit... different. They can only be seen by people who have seen death.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:165},{id:"movies-224",text:"I could see why some of the boys took him for snobby. He had a quiet way about him, a walk and a talk that just wasn't normal around here. He strolled, like a man in a park without a care or a worry in the world, like he had on an invisible coat that would shield him from this place. Yeah, I think it would be fair to say... I liked Andy from the start.",author:"",source:"The Shawshank Redemption",category:"movies",license:"Fair Use",difficulty:"hard",length:354},{id:"movies-225",text:"It now becomes clear that consistency is not a property of a formal system per se, but depends on the interpretation which is proposed for it. By the same token, inconsistency is not an intrinsic property of any formal system.",author:"Gödel",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:226},{id:"movies-226",text:"I guess this time you're really leaving. I heard your suitcase say goodbye. Well, as my broken heart lies bleeding you say true love is suicide. You say you've cried a thousand rivers and now you're swimming for the shore. You left me drowning in my tears and you won't save me anymore.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:286},{id:"movies-227",text:"This is the world that you know. The world as it was at the end of the 20th century. It exists now only as part of a neural interactive simulation that we call the Matrix. You've been living in a dream world, Neo. This is the world as it exists today. Welcome to the desert of the real.",author:"",source:"The Matrix",category:"movies",license:"Fair Use",difficulty:"hard",length:286},{id:"movies-228",text:"Do you know why I survived, professor, the night I got this. Because of her, because she sacrificed herself, because she refused to step aside, because her love was more powerful than Voldemort. I'm not afraid of the name, professor. I'm going to tell you something, something others have only guessed at, it's true, I am the chosen one. Only I can destroy him, but to do so I need to know what Tom Riddle said to you all those years ago in your office, and I need to know what you told him. Be brave, professor, be brave like my mother. Otherwise, you disgrace her, otherwise she died for nothing.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:598},{id:"movies-229",text:"Bad luck, I guess. It floats around. It's got to land on somebody. It was my turn, that's all. I was in the path of the tornado. I just didn't expect the storm would last as long as it has.",author:"",source:"The Shawshank Redemption",category:"movies",license:"Fair Use",difficulty:"hard",length:189},{id:"movies-230",text:"Remember, if the time should come when you have to make a choice between what is right and what is easy, remember what happened to a boy who was good, and kind, and brave, because he strayed across the path of Lord Voldemort. Remember Cedric Diggory.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:250},{id:"movies-231",text:"I think he knows what Rome is. Rome is the mob. Conjure magic for them and they'll be distracted. Take away their freedom and still they'll roar. The beating heart of Rome is not the marble of the senate, it's the sand of the colosseum. He'll bring them death - and they will love him for it.",author:"",source:"Gladiator",category:"movies",license:"Fair Use",difficulty:"hard",length:292},{id:"movies-232",text:"This is why we're here. Because this little gray rock sells for 20 million dollars a kilo. That's the only reason. This is what pays for the whole party, and it's what pays for your science. Those savages are threatening our whole operation. We're on the brink of war and you're supposed to be finding me a diplomatic solution. So use what you've got, and get me some results.",author:"",source:"Avatar",category:"movies",license:"Fair Use",difficulty:"hard",length:376},{id:"movies-233",text:"Let me tell you the story of right hand, left hand. It's a tale of good and evil. Hate: it was with this hand that Cain iced his brother. Love: these five fingers, they go straight to the soul of man. The right hand: the hand of love. The story of life is this: static.",author:"",source:"Do the Right Thing",category:"movies",license:"Fair Use",difficulty:"hard",length:269},{id:"movies-234",text:"I find I'm so excited, I can barely sit still or hold a thought in my head. I think it's the excitement only a free man can feel, a free man at the start of a long journey whose conclusion is uncertain. I hope I can make it across the border. I hope to see my friend and shake his hand. I hope the Pacific is as blue as it has been in my dreams. I hope.",author:"",source:"The Shawshank Redemption",category:"movies",license:"Fair Use",difficulty:"hard",length:353},{id:"movies-235",text:"To be a scientist is to be naive. We are so focused on our search for the truth we fail to consider how few actually want us to find it. But it is always there whether we see it or not, whether we choose to or not. The truth doesn't care about our needs or wants, it doesn't care about our governments, our ideologies, our religions. It will lie in wait for all time. And this, at last, is the gift of Chernobyl. Where I once would fear the cost of truth, now I only ask: What is the cost of lies?",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:497},{id:"movies-236",text:`But the Joker cannot win. Gotham needs its true hero. "You either die a hero, or you live long enough to see yourself become the villain." I can do those things, because I'm not a hero, not like Dent. I killed those people, that's what I can be. I'm whatever Gotham needs me to be. Call it in. You'll hunt me. You'll condemn me, set the dogs on me. Because that's what needs to happen. Because sometimes... the truth isn't good enough. Sometimes people deserve more. Sometimes people deserve to have their faith rewarded.`,author:"",source:"The Dark Knight",category:"movies",license:"Fair Use",difficulty:"hard",length:521},{id:"movies-237",text:"You know, for fifteen years I've been looking for these damn silly lights in the night sky. I've never found any. I'd like to because I believe in life elsewhere.",author:"",source:"Close Encounters of the Third Kind",category:"movies",license:"Fair Use",difficulty:"hard",length:162},{id:"movies-238",text:"You're not perfect, sport, and let me save you the suspense: this girl you've met, she's not perfect either. But the question is whether or not you're perfect for each other.",author:"",source:"Good Will Hunting",category:"movies",license:"Fair Use",difficulty:"hard",length:174},{id:"movies-239",text:"Any attack made by the Rebels against this station would be a useless gesture, no matter what technical data they have obtained. This station is now the ultimate power in the universe! I suggest we use it!",author:"",source:"Star Wars",category:"movies",license:"Fair Use",difficulty:"hard",length:205},{id:"movies-240",text:"We wanted to see if you had the ability to expand your mind to new horizons. And for one brief moment, you did.",author:"",source:"Star Trek",category:"movies",license:"Fair Use",difficulty:"medium",length:111},{id:"movies-241",text:"Every day, every hour, this very minute perhaps, dark forces attempt to penetrate these castle walls. But in the end, their greatest weapon is you. Just something to think about... now off to bed, pip-pip.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:205},{id:"movies-242",text:"Yes, well, those pressures are everywhere in everyone, urging him to what you call savagery. The private hells, the inner needs and mysteries, the beast of instinct. As human beings, that is the way it is. To be human is to be complex. You can't avoid a little ugliness from within and from without.",author:"",source:"Star Trek",category:"movies",license:"Fair Use",difficulty:"hard",length:299},{id:"movies-243",text:"Because some men aren't looking for anything logical, like money. They can't be bought, bullied, reasoned, or negotiated with. Some men just want to watch the world burn.",author:"",source:"The Dark Knight",category:"movies",license:"Fair Use",difficulty:"hard",length:170},{id:"movies-244",text:"You can run far, you can take your small precautions. But have you really gotten away? Can you ever escape? Or is it the truth that you did not have the strength or cunning to hide from destiny? That the world is not small. You are. And, fate can find you anywhere.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:265},{id:"movies-245",text:'Heraclitus: "They vainly purify themselves with blood when they are defiled with it, which is like someone who has stepped into mud using mud to wash himself. Anyone who observed a person doing this would think him mad. And in their ignorance of the true nature of gods and heroes they pray to these statues, which is like someone chatting to a house."',author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:352},{id:"movies-246",text:"No matter how a program twists and turns to get out of itself, it is still following the rules inherent in itself. It is no more possible for it to escape than it is for a human being to decide voluntarily not to obey the laws of physics.",author:"Gödel",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:238},{id:"movies-247",text:"Now, my three friends could hardly fail to notice that I disappeared once a month. I made up all sorts of stories. I told them my mother was ill, and that I had to go home to see her... I was terrified they would desert me the moment they found out what I was. But of course, they, like you, Hermione, worked out the truth...",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:325},{id:"movies-248",text:"You see, what we're talkin' about here is an organism that imitates other life-forms, and it imitates 'em perfectly. When this thing attacked our dogs it tried to digest them... absorb them, and in the process shape its own cells to imitate them. This for instance. That's not dog. It's imitation. We got to it before it had time to finish.",author:"",source:"The Thing",category:"movies",license:"Fair Use",difficulty:"hard",length:340},{id:"movies-249",text:"That's the way it is. It's down there and I'm in here. I guess it comes down to a simple choice, really. Get busy living or get busy dying.",author:"",source:"The Shawshank Redemption",category:"movies",license:"Fair Use",difficulty:"medium",length:139},{id:"movies-250",text:"But he understood at last what Dumbledore had been trying to tell him. It was, he thought, the difference between being dragged into the arena to face a battle to the death and walking into the arena with your head held high. Some people, perhaps, would say that there was little to choose between the two ways, but Dumbledore knew - and so do I, thought Harry, with a rush of fierce pride, and so did my parents - that there was all the difference in the world.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:462},{id:"movies-251",text:"And that's where you're headed, a billion dollar valuation. Unless you take bad advice, in which case you may as well have come up with a chain of very successful yogurt shops. When you go fishing you can catch a lot of fish or you can catch a big fish. You ever walk into a guy's den and see a picture of him standing next to fourteen trout?",author:"",source:"Network",category:"movies",license:"Fair Use",difficulty:"hard",length:342},{id:"movies-252",text:"Is that what your little note says? It must be hard living your life off a couple of scraps of paper. You mix your laundry list with your grocery list you'll end up eating your underwear for breakfast.",author:"",source:"Memento",category:"movies",license:"Fair Use",difficulty:"hard",length:201},{id:"movies-253",text:"The funny thing is, on the outside, I was an honest man, straight as an arrow. I had to come to prison to be a crook.",author:"",source:"The Shawshank Redemption",category:"movies",license:"Fair Use",difficulty:"medium",length:117},{id:"movies-254",text:"But no artist, I now realize, can be satisfied with art alone. There is a natural craving for recognition which cannot be gain-said.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:132},{id:"movies-255",text:"There's a harsh truth to face. No way I'm gonna make it on the outside. All I do anymore is think of ways to break my parole, so maybe they'd send me back. Terrible thing, to live in fear. Brooks Hatlen knew it. Knew it all too well. All I want is to be back where things make sense. Where I won't have to be afraid all the time. Only one thing stops me. A promise I made to Andy.",author:"",source:"The Shawshank Redemption",category:"movies",license:"Fair Use",difficulty:"hard",length:380},{id:"movies-256",text:"If cows and horses or lions had hands, or could draw with their hands and make things as men can, horses would have drawn horse-like gods, cows cow-like gods, and each species would have made the gods' bodies just like their own.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:229},{id:"movies-257",text:"I can teach you how to bewitch the mind and ensnare the senses. I can teach you how to bottle fame, brew glory, and even put a stopper in death. However it seems some of you have come to class to not PAY attention.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:214},{id:"movies-258",text:"I went to the police, like a good American. These two boys were brought to trial. The judge sentenced them to three years in prison, and suspended the sentence.",author:"",source:"The Godfather",category:"movies",license:"Fair Use",difficulty:"hard",length:160},{id:"movies-259",text:"Maybe if we felt any human loss as keenly as we feel one of those close to us, human history would be far less bloody.",author:"",source:"Star Trek",category:"movies",license:"Fair Use",difficulty:"medium",length:118},{id:"movies-260",text:"Seriously, it should have been more dramatic. His brain ought to have been flushing its entire current stock of hypotheses about the universe, none of which allowed this to happen.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:180},{id:"movies-261",text:"Yeah, I read that too. Were you gonna plagiarize the whole thing for us? Do you have any thoughts of your own on this matter? Or do you, is that your thing, you come into a bar, read some obscure passage and then pretend - you pawn it off as your own, as your own idea just to impress some girls, embarrass my friend?",author:"",source:"Good Will Hunting",category:"movies",license:"Fair Use",difficulty:"hard",length:317},{id:"movies-262",text:"The monks used to say that revenge is like a two-headed rat viper. While you watch your enemy go down, you're being poisoned yourself.",author:"",source:"Avatar",category:"movies",license:"Fair Use",difficulty:"medium",length:134},{id:"movies-263",text:"If at first you don't succeed, destroy any evidence that you ever tried.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"easy",length:72},{id:"movies-264",text:`It's the loneliest feeling in the world to find yourself standing up when everybody else is sitting down. To have everybody look at you and say, "What's the matter with him?" I know. I know what it feels like. Walking down an empty street, listening to the sound of your own footsteps. Shutters closed, blinds drawn, doors locked against you. And you aren't sure whether you're walking toward something, or if you're just walking away.`,author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:435},{id:"movies-265",text:"If anything in this life is certain, if history has taught us anything, it is that you can kill anyone.",author:"",source:"The Godfather",category:"movies",license:"Fair Use",difficulty:"medium",length:103},{id:"movies-266",text:"Now calm down. The best thing we can do is go on with our daily routine.",author:"",source:"One Flew Over the Cuckoo's Nest",category:"movies",license:"Fair Use",difficulty:"easy",length:72},{id:"movies-267",text:"Even if it's a dumb story, telling it changes people just the slightest little bit, just as living the story changes me. An infinitesimal change. And that infinitesimal change ripples outward - ever smaller but everlasting. I will get forgotten, but the stories will last. And so we all matter - maybe less than a lot, but always more than none.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:345},{id:"movies-268",text:"Whenever a single definite object is made the supreme end of the State, be it the advantage of a class, the safety of the power of the country, the greatest happiness of the greatest number, or the support of any speculative idea, the State becomes for the time inevitably absolute. Liberty alone demands for its realisation the limitation of the public authority, for liberty is the only object which benefits all alike, and provokes no sincere opposition.",author:"The History of Freedom",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:457},{id:"movies-269",text:"So a rich little man with white hair died. What has that got to do with the price of rice, right? And why is that woe to us? Because you people, and sixty-two million other Americans, are listening to me right now. Because less than three percent of you people read books! Because less than fifteen percent of you read newspapers! Because the only truth you know is what you get over this tube.",author:"",source:"Network",category:"movies",license:"Fair Use",difficulty:"hard",length:394},{id:"movies-270",text:"We all carry around so much pain in our hearts. Love and pain and beauty. They all seem to go together like one little tidy confusing package. It's a messy business, life. It's hard to figure - full of surprises. Some good. Some bad.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:233},{id:"movies-271",text:"I've seen things you people wouldn't believe. Attack ships on fire off the shoulder of Orion. I watched C-beams glitter in the dark near the Tannhauser gate. All those moments will be lost in time, like tears in rain.",author:"",source:"Blade Runner",category:"movies",license:"Fair Use",difficulty:"hard",length:217},{id:"movies-272",text:"I don't hate anybody. The Winklevii aren't suing me for intellectual property theft. They're suing me because for the first time in their lives things didn't go exactly the way they were supposed to for them.",author:"",source:"Network",category:"movies",license:"Fair Use",difficulty:"hard",length:208},{id:"movies-273",text:"After removal from the oven, the pizza is sliced and plated quickly in a flat cardboard box, which is immediately closed and often taped shut. There is no physical separation after the slicing, so that edge can be ignored and we can treat the pizza, for thermal purposes, as an infinite plane. The procedure reduces the heat-transfer problem to one dimension represented by a vector normal to the pizza surface.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:411},{id:"movies-274",text:"As we become aware of our own unavoidable termination, we become aware of the fear-emotion. And I think that, as copulation tends towards self-preservation, all fear tends towards a comprehension of the final ending.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:216},{id:"movies-275",text:"Let me get this straight. You think that your client, one of the wealthiest, most powerful men in the world, is secretly a vigilante who spends his nights beating criminals to a pulp with his bare hands? And your plan is to blackmail this person?",author:"",source:"The Dark Knight",category:"movies",license:"Fair Use",difficulty:"hard",length:246},{id:"movies-276",text:"Mr. Brady, why do you deny the one faculty of man that raises him above the other creatures of the earth? The power of his brain to reason. What other merit have we? The elephant is larger; the horse is swifter and stronger; the butterfly is far more beautiful; the mosquito is more prolific. Even the simple sponge is more durable. But does a sponge think?",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:357},{id:"movies-277",text:"Those whom I could persuade to talk told me that Riddle was obsessed with his parentage. This is understandable, of course; he had grown up in an orphanage and naturally wished to know how he came to be there. It seems that he searched in vain for some trace of Tom Riddle Senior on the shields in the trophy room, on the lists of prefects in the old school records, even in the books of wizarding history. Finally he was forced to accept that his father had never set foot in Hogwarts.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:486},{id:"movies-278",text:"Oh, you think darkness is your ally. But you merely adopted the dark; I was born in it, molded by it. I didn't see the light until I was already a man, by then it was nothing to me but blinding!",author:"",source:"The Dark Knight",category:"movies",license:"Fair Use",difficulty:"hard",length:194},{id:"movies-279",text:"You know, Michael; now that you're so respectable, I think you're more dangerous than ever. I liked you better when you were just a common Mafia hood.",author:"",source:"The Godfather",category:"movies",license:"Fair Use",difficulty:"hard",length:150},{id:"movies-280",text:"What should have been swift revenge turned into an all out war. The City of God was divided. You couldn't go from one section to the other, not even to visit a relative. The cops considered anyone living in the slum a hoodlum. People got used to living in Vietnam, and more and more volunteers signed up to die.",author:"City of God (Cidade de Deus",source:"City of God",category:"movies",license:"Fair Use",difficulty:"hard",length:311},{id:"movies-281",text:"I can show you the world - shining, shimmering, splendid. Tell me, princess, now when did you last let your heart decide? I can open your eyes, take you wonder by wonder. Over, sideways, and under on a magic carpet ride. A whole new world, a new fantastic point of view. No one to tell us no, or where to go, or say we're only dreaming. A whole new world, a dazzling place I never knew. But when I'm way up here, it's crystal clear that now I'm in a whole new world with you.",author:"",source:"Aladdin",category:"movies",license:"Fair Use",difficulty:"hard",length:475},{id:"movies-282",text:"You know, it's funny what a young man recollects. 'Cause I don't remember being born if you know what I mean. I don't recall what I got for my first Christmas and I don't know when I went on my first outdoor picnic. But I do remember the first time I heard the sweetest voice in the wide world.",author:"",source:"Forrest Gump",category:"movies",license:"Fair Use",difficulty:"hard",length:294},{id:"movies-283",text:"As for you, my galvanized friend, you want a heart. You don't know how lucky you are not to have one. Hearts will never be practical until they can be made unbreakable.",author:"",source:"The Wizard of Oz",category:"movies",license:"Fair Use",difficulty:"hard",length:168},{id:"movies-284",text:"Don't worry. As long as you hit that wire with the connecting hook at precisely 88 miles per hour the instant the lightning strikes the tower, everything will be fine.",author:"",source:"Back to the Future",category:"movies",license:"Fair Use",difficulty:"hard",length:167},{id:"movies-285",text:"I never had no trouble with these people. I sat in this window. I watched these little kids get old. And I seen the old people get older. Yeah, sure, some of them don't like us, but most of them do. I mean, for Christ's sake, Pino, they grew up on my food. On my food. And I'm very proud of that.",author:"",source:"Do the Right Thing",category:"movies",license:"Fair Use",difficulty:"hard",length:296},{id:"movies-286",text:"We think Voldemort wants to build up his army, not just witches and wizards, but all manner of dark creatures. He's been recruiting heavily, and we're attempting to do the same.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:177},{id:"movies-287",text:"If you've never programmed a computer, you should. There's nothing like it in the whole world. When you program a computer, it does exactly what you tell it to do. It's like designing a machine - any machine, like a car, like a faucet, like a gas-hinge for a door - using math and instructions. It's awesome in the truest sense: it can fill you with awe.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:354},{id:"movies-288",text:"You think I know the first thing about how hard your life has been, how you feel, who you are, because I read Oliver Twist? Does that encapsulate you?",author:"",source:"Good Will Hunting",category:"movies",license:"Fair Use",difficulty:"hard",length:150},{id:"movies-289",text:"From compositional considerations the tomato layer would be expected to have a relatively high heat capacity and low conductance. It thus serves as a buffer between the mozzarella and the baked dough.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:200},{id:"movies-290",text:"He's not afraid of losing. He's afraid of losing your love. How many ballplayers grow up afraid of losing their fathers' love every time they come up to the plate?",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:163},{id:"movies-291",text:"To carry the art, however, to its highest pitch, it is necessary that the reasoner should be able to utilize all the facts which have come to his knowledge, and this in itself implies, as you will readily see, a possession of all knowledge, which, even in these days of free education and encyclopedias, is a somewhat rare accomplishment. It is not so impossible, however, that a man should possess all knowledge which is likely to be useful to him in his work, and this I have endeavored in my case to do.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:506},{id:"movies-292",text:"Here, the oregano and other trace materials sitting on the surface might be of some importance if they changed the surface radiance in any appreciable way.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:155},{id:"movies-293",text:"The charges against the accused are as follows: that he did knowingly, and in full awareness of the illegality of his actions, produce a patronus charm in the presence of a muggle.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:180},{id:"movies-294",text:"Every artist is a man who has freed himself from his family, his nation, his race. Every man who has shown the world the way to beauty, to true culture, has been a rebel, a 'universal' without patriotism, without home, who has found his people everywhere.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:255},{id:"movies-295",text:"There was this kid I grew up with; he was younger than me. Sorta looked up to me, you know. We did our first work together, worked our way out of the street. Things were good, we made the most of it. During Prohibition, we ran molasses into Canada, made a fortune, your father, too.",author:"",source:"The Godfather",category:"movies",license:"Fair Use",difficulty:"hard",length:282},{id:"movies-296",text:"I believe like a child that suffering will be healed and made up for, that all the humiliating absurdity of human contradictions will vanish like a pitiful mirage, like the despicable fabrication of the impotent and infinitely small Euclidean mind of man, that in the world's finale, at the moment of eternal harmony, something so precious will come to pass that it will suffice for all hearts, for the comforting of all resentments, for the atonement of all the crimes of humanity, for all the blood that they've shed; that it will make it not only possible to forgive but to justify all that has happened.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:607},{id:"movies-297",text:`We know things are bad - worse than bad. They're crazy. It's like everything everywhere is going crazy so we don't go out anymore. We sit in the house and slowly the world we are living in is getting smaller and all we say is, "Please, at least leave us alone in our living rooms. Let me have my toaster and my TV and my steel-belted radials and I won't say anything. Just leave us alone."`,author:"",source:"Network",category:"movies",license:"Fair Use",difficulty:"hard",length:389},{id:"movies-298",text:"If Mr. McMurphy doesn't want to take his medication orally, I'm sure we can arrange that he can have it some other way. But I don't think that he would like it.",author:"",source:"One Flew Over the Cuckoo's Nest",category:"movies",license:"Fair Use",difficulty:"hard",length:160},{id:"movies-299",text:'If you imagine an orange, there may occur in your cortex a set of commands to pick it up, to smell it, to inspect it, and so on. Clearly these commands cannot be carried out, because the orange is not there. But they can be sent along the usual channels towards the cerebellum or other suborgans of the brain, until, at some critical point, a "mental faucet" is closed, preventing them from actually being carried out.',author:"Gödel",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:418},{id:"movies-300",text:"Say to all of you, I have been treated this day with no respect. I've earned you all money. I've made you rich and I asked for little. Good. You will not give, I'll take! As for Don Corleone, well, he makes it very clear to me today that he is my enemy. You must choose between us.",author:"",source:"The Godfather",category:"movies",license:"Fair Use",difficulty:"hard",length:281},{id:"movies-301",text:"It didn't stop you from writing it. As if every thought that tumbles through your head was so clever it would be a crime for it not to be shared. The Internet's not written in pencil, Mark, it's written in ink.",author:"",source:"Network",category:"movies",license:"Fair Use",difficulty:"hard",length:210},{id:"movies-302",text:"I placed my revolver, cocked, upon the top of the wooden case behind which I crouched. Holmes shot the slide across the front of his lantern and left us in pitch darkness - such an absolute darkness as I have never before experienced. The smell of hot metal remained to assure us that the light was still there, ready to flash out at a moment's notice. To me, with my nerves worked up to a pitch of expectancy, there was something depressing and subduing in the sudden gloom, and in the cold dank air of the vault.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:514},{id:"movies-303",text:"My wife deserves vengeance. Doesn't make a difference whether I know about it. Just because there are things I don't remember doesn't make my actions meaningless. The world doesn't just disappear when you close your eyes, does it?",author:"",source:"Memento",category:"movies",license:"Fair Use",difficulty:"hard",length:230},{id:"movies-304",text:"Hope you're feeling better now, hope you got my letter, how is my stormy weather now, is it gonna change? Can I be like everyone, pretending that there's nothing wrong? Remember when we walked upon clouds that never rain? But every cloud must drain...",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:251},{id:"movies-305",text:"You have no idea what I want. What is chess, do you think? Those who play for fun or not at all dismiss it as a game. The ones who devote their lives to it for the most part insist that it's a science. It's neither. Bobby Fischer got underneath it like no one before and found at its center art. I spent my life trying to play like him. Most of these guys have. But we're like forgers. We're competent fakes. His successor wasn't here tonight. He wasn't here. He is asleep in his room in your house. Your son creates like Fischer. He sees like him, inside.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:556},{id:"movies-306",text:"Sometimes you remind me a lot of James. He called it my 'furry little problem' in company. Many people were under the impression that I owned a badly behaved rabbit.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:165},{id:"movies-307",text:"I believe that you are sincere and good at heart. If you do not attain happiness, always remember that you are on the right road, and try not to leave it. Above all, avoid falsehood, every kind of falsehood, especially falseness to yourself. Watch over your own deceitfulness and look into it every hour, every minute. Avoid being scornful, both to others and to yourself. What seems to you bad within you will grow purer from the very fact of your observing it in yourself.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:474},{id:"movies-308",text:"We deal in illusions, man! None of it is true! But you people sit there, day after day, night after night, all ages, colors, creeds... We're all you know. You're beginning to believe the illusions we're spinning here. You're beginning to think that the tube is reality, and that your own lives are unreal. You do whatever the tube tells you! You dress like the tube, you eat like the tube, you raise your children like the tube, you even think like the tube! This is mass madness, you maniacs!",author:"",source:"Network",category:"movies",license:"Fair Use",difficulty:"hard",length:493},{id:"movies-309",text:"Now this one upsets me. We have an out-of-tune player. Before I go any further, does that player want to do the right thing and reveal himself? Okay. Maybe a bug flew in my ear... No, I guess my ears are clean because we most definitely have an out-of-tune player. Whoever it is, this is your last chance. Either you know you are out of tune, and are therefore deliberately sabotaging my band; or you do not know you're out of tune - which I'm afraid is even worse.",author:"",source:"Whiplash",category:"movies",license:"Fair Use",difficulty:"hard",length:465},{id:"movies-310",text:"After living with you for the last six months, I'm turning into one of your scripts. Well, this is not a script, Diana. There's some real, actual life going on here.",author:"",source:"Network",category:"movies",license:"Fair Use",difficulty:"hard",length:165},{id:"movies-311",text:"This business is filled to the brim with unrealistic people who thought their bods aged like wine. If you mean it turns to vinegar, it does. If you mean it gets better with age, it don't. Besides Butch, how many fights you think you got left in you anyway? Two? Boxers don't have an old timer's pension. You came close, but you never made it, and if you were gonna make it, you woulda made it by now.",author:"",source:"Pulp Fiction",category:"movies",license:"Fair Use",difficulty:"hard",length:400},{id:"movies-312",text:"Well, gentlemen, in my opinion, if we send him back to Pendleton or we send him up to Disturbed, it's just one more way of passing on our problems to somebody else. You know we don't like to do that, so I'd like to keep him on the ward. I think we can help him.",author:"",source:"One Flew Over the Cuckoo's Nest",category:"movies",license:"Fair Use",difficulty:"hard",length:261},{id:"movies-313",text:"Look, you're supposed to be winning the hearts and minds of the natives. Isn't that the whole point of your little puppet show? If you walk like them, you talk like them, they'll trust you. We build them a school, teach them English. But after - how many years - the relations with the indigenous are only getting worse.",author:"",source:"Avatar",category:"movies",license:"Fair Use",difficulty:"hard",length:320},{id:"movies-314",text:"His chess ideas are like pieces of his body he's reluctant to give up. For instance, he simply can't cope with being told not to bring his queen out too early in the game. Why shouldn't he? He's won many a game in Washington Square doing exactly that, why is this suddenly wrong?",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:279},{id:"movies-315",text:"I wonder if the Emperor Honorius watching the Visigoths coming over the seventh hill could truly realize that the Roman Empire was about to fall. This is really just another page of history, isn't it? Will this be the end of our civilization? Turn the page.",author:"",source:"Star Trek",category:"movies",license:"Fair Use",difficulty:"hard",length:257},{id:"movies-316",text:"Now, remember. According to my theory, you interfered with your parents' first meeting. If they don't meet, they won't fall in love, they won't get married, and they won't have kids. That's why your older brother's disappearing from that photograph. Your sister will follow, and unless you repair the damage, you'll be next.",author:"",source:"Back to the Future",category:"movies",license:"Fair Use",difficulty:"hard",length:324},{id:"movies-317",text:"Study hard, and you will be rewarded. Fail to do so, and the consequences may be... severe.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"medium",length:91},{id:"movies-318",text:"I don't have to tell you things are bad. Everybody knows things are bad. It's a depression. Everybody's out of work or scared of losing their job. The dollar buys a nickel's worth, banks are going bust, shopkeepers keep a gun under the counter. Punks are running wild in the street and there's nobody anywhere who seems to know what to do and there's no end to it. We know the air is unfit to breathe and our food is unfit to eat, and we sit watching our TVs while some local newscaster tells us that today we had fifteen homicides and sixty-three violent crimes, as if that's the way it's supposed to be.",author:"",source:"Network",category:"movies",license:"Fair Use",difficulty:"hard",length:605},{id:"movies-319",text:"The melted mozzarella layer, which we shall designate MML, is the obvious source of trauma to the roof of the mouth and from the point of view of medical physics is clearly the key agent in the etiology of pizza burn.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:217},{id:"movies-320",text:"When a man's an empty kettle, he should be on his mettle, and yet I'm torn apart. Just because I'm presumin' that I could be kinda human if I only had a heart.",author:"",source:"The Wizard of Oz",category:"movies",license:"Fair Use",difficulty:"hard",length:159},{id:"movies-321",text:"Just as people behave to me, so do I behave to them. When I see that a person despises me and treats me with contempt, I can be as proud as any peacock.",author:"",source:"Amadeus",category:"movies",license:"Fair Use",difficulty:"hard",length:152},{id:"movies-322",text:"A place where there isn't any trouble. Do you suppose there is such a place, Toto? There must be. It's not a place you can get to by a boat or a train. It's far, far away. Behind the moon, beyond the rain...",author:"",source:"The Wizard of Oz",category:"movies",license:"Fair Use",difficulty:"hard",length:207},{id:"movies-323",text:"There's only one person in the world who's going to decide what I'm going to do and that's me.",author:"",source:"Citizen Kane",category:"movies",license:"Fair Use",difficulty:"medium",length:94},{id:"movies-324",text:"The portly client puffed out his chest with an appearance of some little pride and pulled a dirty and wrinkled newspaper from the inside pocket of his greatcoat. As he glanced down the advertisement column, with his head thrust forward and the paper flattened out upon his knee, I took a good look at the man and endeavored, after the fashion of my companion, to read the indications which might be presented by his dress or appearance.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:436},{id:"movies-325",text:"I didn't wanna spend my twenties as a professional defendant. Who knew the music industry doesn't have a sense of humor? We tried to sell the company to pay the 35 million they said we owed in royalties, but I guess to them that was a little like selling a stolen car to pay for the stolen gas.",author:"",source:"Network",category:"movies",license:"Fair Use",difficulty:"hard",length:294},{id:"movies-326",text:"Yes, not only humans but also every other organism in the cosmos, as well as the planets or moons on which they thrive, would not exist but for the wreckage of spent stars. So you're made of detritus. Get over it. Or better yet, celebrate it. After all, what nobler thought can one cherish than that the universe lives within us all?",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:333},{id:"movies-327",text:"We began to recognize in them a strange obsession. After all, they are emotionally inexperienced, with only a few years in which to store up the experiences which you and I take for granted. If we gift them with a past, we create a cushion or a pillow for their emotions, and consequently, we can control them better.",author:"",source:"Blade Runner",category:"movies",license:"Fair Use",difficulty:"hard",length:317},{id:"movies-328",text:"Do I really look like a guy with a plan? You know what I am? I'm a dog chasing cars. I wouldn't know what to do with one if I caught it. You know, I just do things. The Mob has plans, the cops have plans, Gordon's got plans, you know, they're schemers. Schemers trying to control their worlds. I'm not a schemer. I try to show the schemers how pathetic their attempts to control things really are.",author:"",source:"The Dark Knight",category:"movies",license:"Fair Use",difficulty:"hard",length:397},{id:"movies-329",text:"Let me tell you something my friend. Hope is a dangerous thing. Hope can drive a man insane.",author:"",source:"The Shawshank Redemption",category:"movies",license:"Fair Use",difficulty:"medium",length:92},{id:"movies-330",text:"Do you buy all these books retail or do you send away for like a shrink kit that comes with all these volumes included?",author:"",source:"Good Will Hunting",category:"movies",license:"Fair Use",difficulty:"medium",length:119},{id:"movies-331",text:"Look at the stars. Same stars as last week, last year, when we were kids, before we were even born. In a hundred years no one will ever know who we were. They'll know those same stars.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:184},{id:"movies-332",text:"They wanted me to build them a bomb so I took their plutonium and in turn gave them a shoddy bomb casing full of used pinball machine parts. Come on! Let's get you a radiation suit. We must prepare to reload.",author:"",source:"Back to the Future",category:"movies",license:"Fair Use",difficulty:"hard",length:208},{id:"movies-333",text:"No! Fool that I am! I should have remembered! Those slippers will never come off as long as you're alive. But that's not what's worrying me. It's how to do it. These things must be done delicately or you hurt the spell.",author:"",source:"The Wizard of Oz",category:"movies",license:"Fair Use",difficulty:"hard",length:219},{id:"movies-334",text:"By studying the cooling of pizza in the gravity free environment of the space shuttle, we could more exactly determine the importance of convective flows.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:154},{id:"movies-335",text:"That day, for no particular reason, I decided to go for a little run. So I ran to the end of the road. And when I got there, I thought maybe I'd run to the end of town. And when I got there, I thought maybe I'd just run across Greenbow County. And I figured, since I run this far, maybe I'd just run across the great state of Alabama.",author:"",source:"Forrest Gump",category:"movies",license:"Fair Use",difficulty:"hard",length:334},{id:"movies-336",text:"I took for granted all the times that I thought would last somehow. I hear the laughter, I taste the tears, but I can't get near you now.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:137},{id:"movies-337",text:"Your sins are terrible. It is just that you suffer. Your life could be redeemed, but I know you don't believe that. You will not change.",author:"",source:"The Godfather",category:"movies",license:"Fair Use",difficulty:"medium",length:136},{id:"movies-338",text:"Obviously, if I was serious about having a relationship with someone long-term, the last people I would introduce him to would be my family.",author:"Are You There",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:140},{id:"movies-339",text:"I'll miss the sea, but a person needs new experiences. They jar something deep inside, allowing him to grow. Without change something sleeps inside us, and seldom awakens. The sleeper must awaken.",author:"",source:"Dune",category:"movies",license:"Fair Use",difficulty:"hard",length:196},{id:"movies-340",text:"Directories contain elements that describe objects in the world, such as computers, folders, objects, managed resources, and even people. These elements have names and, like the fields in a database, changing values.",author:"",source:"Network",category:"movies",license:"Fair Use",difficulty:"hard",length:216},{id:"movies-341",text:"Look, I'm gonna give you your choice. I'm not gonna be biased in any way. Tomorrow night you can either play Goofy Golf, which is a lot of standing in line and shoving and pushing and probably getting a zero, or you can see Pinocchio, which is a lot of furry animals and magic, and you'll have a wonderful time. Okay? Now let's vote.",author:"",source:"Close Encounters of the Third Kind",category:"movies",license:"Fair Use",difficulty:"hard",length:333},{id:"movies-342",text:"I know what you think it means, sonny. To me, it's just a made up word. A politician's word, so young fellas like yourself can wear a suit and a tie, and have a job. What do you really want to know? Am I sorry for what I did?",author:"",source:"The Shawshank Redemption",category:"movies",license:"Fair Use",difficulty:"hard",length:225},{id:"movies-343",text:"As he spoke the gleam of the sidelights of a carriage came round the curve of the avenue. It was a smart little landau which rattled up to the door of Briony Lodge. As it pulled up, one of the loafing men at the corner dashed forward to open the door in the hope of earning a copper, but was elbowed away by another loafer, who had rushed up with the same intention. A fierce quarrel broke out, which was increased by the two guardsmen, who took sides with one of the loungers, and by the scissors-grinder, who was equally hot upon the other side.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:547},{id:"movies-344",text:'But here we will not try to pass judgment on the objective value of actions; we will be concerned instead with the more modest task of describing the subjective order that a unified purpose brings to individual consciousness. In this sense the answer to the old riddle "What is the meaning of life?" turns out to be astonishingly simple. The meaning of life is meaning: whatever it is, wherever it comes from, a unified purpose is what gives meaning to life.',author:"",source:"Psycho",category:"movies",license:"Fair Use",difficulty:"hard",length:458},{id:"movies-345",text:"Kid, I've flown from one side of this galaxy to the other, and I've seen a lot of strange stuff. But I've never seen anything to make me believe that there's one all-powerful Force controlling everything. There's no mystical energy field that controls MY destiny.",author:"",source:"Star Wars",category:"movies",license:"Fair Use",difficulty:"hard",length:263},{id:"movies-346",text:"Err, what would Uncle say? Sometimes clouds have two sides, a dark and light. And a silver lining in between. It's like a silver sandwich. So... when life seems hard... take a bite out of the silver sandwich.",author:"",source:"Avatar",category:"movies",license:"Fair Use",difficulty:"hard",length:208},{id:"movies-347",text:"Why study science? Science, more than any other discipline, provides us with tools to learn about the world. Science is not a listing of facts; science is an invitation to observe the world, ask questions, and puzzle over problems and enjoy the process of solving them. From the time children begin to perceive their environment, they are involved in science.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:359},{id:"movies-348",text:"Harry could hardly believe this was real. Four weeks with nothing, not the tiniest hint of a plan to remove him from Privet Drive, and suddenly a whole bunch of wizards were standing matter-of-factly in the house as though this were a long-standing arrangement. He glanced at the people surrounding Lupin; they were still gazing avidly at him. He felt very conscious of the fact that he had not combed his hair for four days.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:425},{id:"movies-349",text:"I think what our insightful young friend is saying is that we welcome the inevitable seasons of nature, but we're upset by the seasons of our economy.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:150},{id:"movies-350",text:"The way I see it if you're going to build a time machine into a car why not do it with some style? Besides, the stainless steel construction made the flux dispersal - look out!",author:"",source:"Back to the Future",category:"movies",license:"Fair Use",difficulty:"hard",length:176},{id:"movies-351",text:"I can see the sun, but even if I cannot see the sun, I know that it exists. And to know that the sun is there - that is living.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:127},{id:"movies-352",text:"A fellow will remember a lot of things you wouldn't think he'd remember. You take me. One day, back in 1896, I was crossing over to Jersey on the ferry, and as we pulled out, there was another ferry pulling in, and on it there was a girl waiting to get off. A white dress she had on. She was carrying a white parasol. I only saw her for one second. She didn't see me at all, but I'll bet a month hasn't gone by since that I haven't thought of that girl.",author:"",source:"Citizen Kane",category:"movies",license:"Fair Use",difficulty:"hard",length:453},{id:"movies-353",text:"Oh, yes. The past can hurt. But the way I see it, you can either run from it... or learn from it.",author:"",source:"The Lion King",category:"movies",license:"Fair Use",difficulty:"medium",length:97},{id:"movies-354",text:"Wrongfully imprisoned action heroes rarely have the time to wait for an appeal. Often, the fate of a loved one or the free world itself is at stake if you do not get out, and so any experienced action hero knows that a dramatic rescue, a prison break, or a pardon will almost certainly be coming in time for Act III.",author:"The Action Hero's Handbook: How to Catch a Great White Shark",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:316},{id:"movies-355",text:"We lived on farms, then we lived in cities, and now we're going to live on the internet!",author:"",source:"Network",category:"movies",license:"Fair Use",difficulty:"medium",length:88},{id:"movies-356",text:"Well, that's their own stupidity, I should have been there. Well, darkness is the absence of light, and the stupidity in that instance was the absence of me... Catherine, I've got students in my office now. Students. Undergrads. I don't know, from the looks of it, they want to sell me a Brooks Brothers franchise.",author:"",source:"Network",category:"movies",license:"Fair Use",difficulty:"hard",length:314},{id:"movies-357",text:"We love people who've died... where's the social utility in that? Maybe it means something more - something we can't yet understand. Maybe it's some evidence, some artifact of a higher dimension that we can't consciously perceive. I'm drawn across the universe to someone I haven't seen in a decade, who I know is probably dead. Love is the one thing we're capable of perceiving that transcends dimensions of time and space. Maybe we should trust that, even if we can't understand it yet.",author:"",source:"Interstellar",category:"movies",license:"Fair Use",difficulty:"hard",length:488},{id:"movies-358",text:"I took up my vocation, I was called by my nation. Without hesitation, my answer I gave. Now I am not wondering the things that I might have been. I'm no consolation to the forgotten brave.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:188},{id:"movies-359",text:"Somewhere over the rainbow way up high, there's a land that I heard of once in a lullaby. Somewhere over the rainbow skies are blue, and the dreams that you dare to dream really do come true. Someday I'll wish upon a star and wake up where the clouds are far behind me. Where troubles melt like lemon drops away above the chimney tops, that's where you'll find me. Somewhere over the rainbow bluebirds fly. Birds fly over the rainbow. Why then, oh, why can't I?",author:"",source:"The Wizard of Oz",category:"movies",license:"Fair Use",difficulty:"hard",length:461},{id:"movies-360",text:`You found paradise in America. You had a good trade, made a good living, the police protected you and there were courts of law and you didn't need a friend like me. But, now you come to me and you say, "Don Corleone, give me justice." But you don't ask with respect. You don't offer friendship. You don't even think to call me Godfather.`,author:"",source:"The Godfather",category:"movies",license:"Fair Use",difficulty:"hard",length:337},{id:"movies-361",text:"Unbelievable, that old Biff could have chosen that particular date. It could mean that that point in time inherently contains some sort of cosmic significance. Almost as if it were the temporal junction point for the entire space-time continuum. On the other hand, it could just be an amazing coincidence.",author:"",source:"Back to the Future",category:"movies",license:"Fair Use",difficulty:"hard",length:305},{id:"movies-362",text:"Do you know I've been sitting here thinking to myself: that if I didn't believe in life, if I lost faith in the woman I love, lost faith in the order of things, were convinced in fact that everything is a disorderly, damnable, and perhaps devil-ridden chaos, if I were struck by every horror of man's disillusionment - still I should want to live.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:347},{id:"movies-363",text:"There are times, sir, when men of good conscience cannot blindly follow orders. You acknowledge their sentience, but ignore their personal liberties and freedom. Order a man to turn his child over to the state? Not while I'm his captain.",author:"",source:"Star Trek",category:"movies",license:"Fair Use",difficulty:"hard",length:237},{id:"movies-364",text:"Do you smell that? Napalm, son. Nothing else in the world smells like that. I love the smell of napalm in the morning. You know, one time we had a hill bombed, for twelve hours. Smelled like victory. Someday this war's gonna end.",author:"",source:"Apocalypse Now",category:"movies",license:"Fair Use",difficulty:"hard",length:229},{id:"movies-365",text:"We are what we pretend to be, so we must be very careful about what we pretend to be.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:85},{id:"movies-366",text:"Say, you're a lot smaller than my last master. Either that, or I'm getting bigger. Look at me from the side. Do I look different to you?",author:"",source:"Aladdin",category:"movies",license:"Fair Use",difficulty:"medium",length:136},{id:"movies-367",text:"I know now that it's over. I knew it then. There would be no way, Michael, no way you could ever forgive me, not with this Sicilian thing that's been going on for 2,000 years.",author:"",source:"The Godfather",category:"movies",license:"Fair Use",difficulty:"hard",length:175},{id:"movies-368",text:"At three o'clock precisely I was at Baker Street, but Holmes had not yet returned. The landlady informed me that he had left the house shortly after eight o'clock in the morning. I sat down beside the fire, however, with the intention of awaiting him, however long he might be. I was already deeply interested in his inquiry, for, though it was surrounded by none of the grim and strange features which were associated with the two crimes which I have already recorded, still, the nature of the case and the exalted station of his client gave it a character of its own.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:569},{id:"movies-369",text:"For so long I thought that if my dad accepted me, I'd be happy. I'm back home now. My dad talks to me, he even thinks I'm a hero. Everything should be perfect, right? I should be happy now, but I'm not. I'm angrier than ever and I don't know why.",author:"",source:"Avatar",category:"movies",license:"Fair Use",difficulty:"hard",length:246},{id:"movies-370",text:"If I'm laden at all, I'm laden with sadness that everyone's heart isn't filled with the gladness of love for one another.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:121},{id:"movies-371",text:"All he ever wanted out of life was love. You see, he just didn't have any to give.",author:"",source:"Citizen Kane",category:"movies",license:"Fair Use",difficulty:"medium",length:82},{id:"movies-372",text:"A long time ago, I was in Burma, my friends and I were working for the local government. They were trying to buy the loyalty of tribal leaders by bribing them with precious stones. But their caravans were being raided in a forest north of Rangoon by a bandit. So we went looking for the stones. But in six months, we never found anyone who traded with him. Then, one day I saw a child playing with a ruby the size of a tangerine. The bandit had been throwing them away.",author:"",source:"The Dark Knight",category:"movies",license:"Fair Use",difficulty:"hard",length:469},{id:"movies-373",text:"I took a wrong turn on the way to the bathroom and found myself in a beautifully proportioned room I had never seen before, containing a really rather magnificent collection of chamberpots. When I went back to investigate more closely, I discovered that the room had vanished. But I must keep an eye out for it. Possibly it is only accessible at five thirty in the morning. Or it may only appear at the quarter moon - or when the seeker has an exceptionally full bladder.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:471},{id:"movies-374",text:"He didn't teach you how to win, he taught you how not to lose. That's nothing to be proud of. You're playing not to lose, Josh. You've got to risk losing. You've got to risk everything. You've got to go to the edge of defeat. That's where you want to be, boy - on the edge of defeat.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:283},{id:"movies-375",text:"Voldemort himself created his worst enemy, just as tyrants everywhere do! Have you any idea how much tyrants fear the people they oppress? All of them realize that, one day, amongst their many victims, there is sure to be one who rises against them and strikes back!",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:266},{id:"movies-376",text:"You're right, I did lose a million dollars last year. I expect to lose a million dollars this year. I expect to lose a million dollars next year. You know, Mr. Thatcher, at the rate of a million dollars a year, I'll have to close this place in 60 years.",author:"",source:"Citizen Kane",category:"movies",license:"Fair Use",difficulty:"hard",length:253},{id:"movies-377",text:"Okay, stand outa the way. Sometimes when I go to exertin' myself I use up all the air nearby and grown men faint from suffocation. Stand back. There's liable to be crackin' cement and flying steel. Get the women and kids someplace safe. Stand back...",author:"",source:"One Flew Over the Cuckoo's Nest",category:"movies",license:"Fair Use",difficulty:"hard",length:250},{id:"movies-378",text:"Alchemy; the science of understanding the structure of matter, breaking it down, then reconstructing it as something else. It can even make gold from lead. But alchemy is a science, so it must follow the natural laws: To create, something of equal value must be lost. This is the principle of Equivalent Exchange. But on that night, I learned the value of some things can't be measured on a simple scale. My brother and I knew the laws of science, of Equivalent Exchange, that gain required sacrifice, that something had to be taken from us. But we thought there was nothing more we could lose, we were wrong...",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:611},{id:"movies-379",text:"Considering the marvelous complexity of the universe, its clockwork perfection, its balances of this against that... matter, energy, gravitation, time, dimension, I believe that our existence must be more than either of these philosophies. That what we are goes beyond Euclidean or other practical measuring systems and that our existence is part of a reality beyond what we understand now as reality.",author:"",source:"Star Trek",category:"movies",license:"Fair Use",difficulty:"hard",length:401},{id:"movies-380",text:"He talked about terrible meetings in lonely places, of cyclopean ruins in the heart of the Maine woods beneath which vast staircases led down to abysses of nighted secrets, of complex angles that led through invisible walls to other regions of space and time, and of hideous exchanges of personality that permitted explorations in remote and forbidden places, on other worlds, and in different space-time continua.",author:"",source:"The Thing",category:"movies",license:"Fair Use",difficulty:"hard",length:414},{id:"movies-381",text:"You, my friend, are a victim of disorganized thinking. You are under the unfortunate impression that just because you run away you have no courage; you're confusing courage with wisdom.",author:"",source:"The Wizard of Oz",category:"movies",license:"Fair Use",difficulty:"hard",length:185},{id:"movies-382",text:"A generous spirit prefers that his country should be poor, and weak, and of no account, but free, rather than powerful, prosperous, and enslaved. It is better to be the citizen of a humble commonwealth in the Alps, without a prospect of influence beyond the narrow frontier, than a subject of the superb autocracy that overshadows half of Asia and of Europe.",author:"The History of Freedom",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:358},{id:"movies-383",text:"You have needs - satisfy them. You have as much right as the rich and the mighty. Don't hesitate to satisfy your needs; indeed, expand your needs and demand more.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:162},{id:"movies-384",text:"Soon after arriving, he offended the Icelanders by calling their country inadequate because it had no bowling alleys. He complained about the TV cameras, about the lighting, about the table and chairs, and the contrast of the squares on the board. His hotel room, he said, had too nice a view. None of this has anything to do with chess of course. But maybe it did. If he won, he'd be the first American world champion in history. If he lost, he'd just be another patzer from Brooklyn.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:485},{id:"movies-385",text:"I felt a great disturbance in the Force, as if millions of voices suddenly cried out in terror and were suddenly silenced. I fear something terrible has happened.",author:"",source:"Star Wars",category:"movies",license:"Fair Use",difficulty:"hard",length:162},{id:"movies-386",text:"Sometimes it seems as though each new step towards AI, rather than producing something which everyone agrees is real intelligence, merely reveals what real intelligence is not.",author:"Gödel",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:176},{id:"movies-387",text:"Yes. Everyone at Harvard's inventing something. Harvard undergraduates believe that inventing a job is better than finding a job. So I'll suggest again that the two of you come up with a new new project.",author:"",source:"Network",category:"movies",license:"Fair Use",difficulty:"hard",length:203},{id:"movies-388",text:"What good's a reward if you ain't around to use it? Besides, attacking that battle station ain't my idea of courage. It's more like... suicide.",author:"",source:"Star Wars",category:"movies",license:"Fair Use",difficulty:"medium",length:143},{id:"movies-389",text:"Very well - I'll bide my time. And as for you, my fine lady, it's true I can't attend to you here and now as I'd like, but just try to stay out of my way - just try! I'll get you, my pretty, and your little dog too!",author:"",source:"The Wizard of Oz",category:"movies",license:"Fair Use",difficulty:"hard",length:215},{id:"movies-390",text:"At the time when Britain faced a plunge into chaos and darkness, a hero emerged who not only succeeded in getting the feuding tribes to work together against their common enemy, but led them in a series of smashing victories that established him as a figure of great power and importance - a figure ripe for developing into the myth-laden king of later accounts.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:362},{id:"movies-391",text:"You come into my house on the day my daughter is to be married and you ask me to do murder - for money.",author:"",source:"The Godfather",category:"movies",license:"Fair Use",difficulty:"medium",length:103},{id:"movies-392",text:"I would never want to forfeit my genders. Along with Aunt Augusta, I would rather say to the English language that to lose one gender may be regarded as a misfortune; to lose both looks like carelessness.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:204},{id:"movies-393",text:"I find to my amazement that the more I love mankind as a whole, the less I love man in particular.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:98},{id:"movies-394",text:"Slowly and solemnly he was borne into Briony Lodge and laid out in the principal room, while I still observed the proceedings from my post by the window. The lamps had been lit, but the blinds had not been drawn, so that I could see Holmes as he lay upon the couch. I do not know whether he was seized with compunction at that moment for the part he was playing, but I know that I never felt more heartily ashamed of myself in my life than when I saw the beautiful creature against whom I was conspiring, or the grace and kindliness with which she waited upon the injured man.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:576},{id:"movies-395",text:"You know, you really don't need a forensics team to get to the bottom of this. If you guys were the inventors of Facebook, you'd have invented Facebook.",author:"",source:"Network",category:"movies",license:"Fair Use",difficulty:"hard",length:152},{id:"movies-396",text:"I'll make him an offer he can't refuse. You see, Johnny, we feel that entertainment is going to be a big factor in drawing gamblers into the casinos. We're hoping that you'll sign a contract agreeing to appear five times a year. Perhaps convince some of your friends in the movies to do the same. We're counting on you, Johnny.",author:"",source:"The Godfather",category:"movies",license:"Fair Use",difficulty:"hard",length:327},{id:"movies-397",text:"Convection also plays a minor role because of the relative thinness of the air layer and the presence of the upper cardboard heat shield. The insulation properties of the cardboard play a major role, since they serve to minimize the temperature gradient across the airspace. By studying the cooling of pizza in the gravity free environment of the space shuttle, we could more exactly determine the importance of convective flows.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:429},{id:"movies-398",text:"Well, the time has come to say, is dehumanization such a bad word? Because good or bad, that's what is so. The whole world is becoming humanoid - creatures that look human but aren't. The whole world, not just us. We're just the most advanced country so we're getting there first. The whole world's people are becoming mass-produced, programmed, numbered, insensate things.",author:"",source:"Network",category:"movies",license:"Fair Use",difficulty:"hard",length:373},{id:"movies-399",text:"I was stealing saltshakers again. Ten, sometimes twelve a night, shoving them in my pockets, hiding them up my sleeves, smuggling them out of bars and diners and anywhere else I could find them. In the morning, wherever I woke up, I was always covered in salt. I was cured meat. I had become beef jerky. Even as a small, small child, I knew it would one day come to this.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:371},{id:"movies-400",text:"The Matrix is everywhere. It is all around us. Even now, in this very room. You can see it when you look out your window, or when you turn on your television.",author:"",source:"The Matrix",category:"movies",license:"Fair Use",difficulty:"hard",length:158},{id:"movies-401",text:"And you're to tell him nothing personal, Starling. Believe me, you don't want Hannibal Lecter inside your head.",author:"",source:"The Silence of the Lambs",category:"movies",license:"Fair Use",difficulty:"medium",length:111},{id:"movies-402",text:"The general who became a slave. The slave who became a gladiator. The gladiator who defied an emperor. Striking story! But now, the people want to know how the story ends. Only a famous death will do. And what could be more glorious than to challenge the Emperor himself in the great arena?",author:"",source:"Gladiator",category:"movies",license:"Fair Use",difficulty:"hard",length:290},{id:"movies-403",text:"I have already told you, I have no further stocks of Veritaserum. Unless you wish to poison Potter - and I can assure you I would have the greatest sympathy if you did - I cannot help you. The only trouble is that most venoms act too swiftly to give the victim much in the way of time for truth telling.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:303},{id:"movies-404",text:"Well - it's just that you seem to be labouring under the delusion that I am going to - what is the phrase? - come quietly. I am afraid I am not going to come quietly at all, Cornelius. I have absolutely no intention of being sent to Azkaban. I could break out, of course - but what a waste of time, and frankly, I can think of a whole host of things I would rather be doing.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:374},{id:"movies-405",text:"My dear young man, don't take it too hard. Your work is ingenious. It's quality work. And there are simply too many notes, that's all. Just cut a few and it'll be perfect. - Which few did you have in mind, Majesty?",author:"",source:"Amadeus",category:"movies",license:"Fair Use",difficulty:"hard",length:214},{id:"movies-406",text:"Here in town there's only she who is beautiful as me, so I'm making plans to woo and marry Belle.",author:"",source:"Beauty and the Beast",category:"movies",license:"Fair Use",difficulty:"medium",length:97},{id:"movies-407",text:"There are things being negotiated now that are going to solve all of your problems and answer all of your questions. That's all I can tell you now. Carlo, you grew up in Nevada. When we make our move there you're going to be my right hand man. Tom Hagen is no longer Consigliari. He's going to be our lawyer in Vegas. That's no reflection on Tom, it's just the way I want it. Besides, if I ever need help, who's a better Consigliari than my father? And that's it.",author:"",source:"The Godfather",category:"movies",license:"Fair Use",difficulty:"hard",length:463},{id:"movies-408",text:"Yet you have never been there. You have not seen what it has become. I am dying, Maximus. When a man sees his end... he wants to know there was some purpose to his life. How will the world speak my name in years to come? Will I be known as the philosopher? The warrior? The tyrant...? Or will I be the emperor who gave Rome back her true self? There was once a dream that was Rome. You could only whisper it. Anything more than a whisper and it would vanish... it was so fragile. And I fear that it will not survive the winter.",author:"",source:"Gladiator",category:"movies",license:"Fair Use",difficulty:"hard",length:527},{id:"movies-409",text:"Why, anybody can have a brain. That's a very mediocre commodity. Every pusillanimous creature that crawls on the Earth or slinks through slimy seas has a brain. Back where I come from, we have universities, seats of great learning, where men go to become great thinkers. And when they come out, they think deep thoughts and with no more brains than you have. But they have one thing you haven't got: a diploma.",author:"",source:"The Wizard of Oz",category:"movies",license:"Fair Use",difficulty:"hard",length:410},{id:"movies-410",text:"I didn't tell Mama anything. I was just about to come up and wake you so that I could tell you.",author:"",source:"The Godfather",category:"movies",license:"Fair Use",difficulty:"medium",length:95},{id:"movies-411",text:"See, the sad thing about a guy like you is in 50 years you're gonna start doin' some thinkin' on your own and you're going to come up with the fact that there are two certainties in life: one, don't do that, and two, you dropped 150 grand on an education you could have got for $1.50 in late charges at the public library!",author:"",source:"Good Will Hunting",category:"movies",license:"Fair Use",difficulty:"hard",length:322},{id:"movies-412",text:"Water. Earth. Fire. Air. Long ago the four nations lived together in harmony. Then, everything changed when the Fire Nation attacked. Only the Avatar, master of all four elements, could stop them, but when the world needed him most, he vanished. A hundred years passed and my brother and I discovered the new Avatar, an airbender named Aang. And although his airbending skills are great, he has a lot to learn before he's ready to save anyone. But I believe Aang can save the world.",author:"",source:"Avatar",category:"movies",license:"Fair Use",difficulty:"hard",length:482},{id:"movies-413",text:"Look, a guy who builds a nice chair doesn't owe money to everyone who ever has built a chair, okay? They came to me with an idea, I had a better one.",author:"",source:"Network",category:"movies",license:"Fair Use",difficulty:"medium",length:149},{id:"movies-414",text:"I was going to the worst place in the world and I didn't even know it yet. Weeks away and hundreds of miles up a river that snaked through the war like a main circuit cable plugged straight into Kurtz. It was no accident that I got to be the caretaker of Colonel Walter E. Kurtz's memory any more than being back in Saigon was an accident. There is no way to tell his story without telling my own. And if his story really is a confession, then so is mine.",author:"",source:"Apocalypse Now",category:"movies",license:"Fair Use",difficulty:"hard",length:455},{id:"movies-415",text:"Computers make excellent and efficient servants, but I have no wish to serve under them. Captain, a starship also runs on loyalty to one man, and nothing can replace it or him.",author:"",source:"Star Trek",category:"movies",license:"Fair Use",difficulty:"hard",length:176},{id:"movies-416",text:"And Peeves, whom Harry had never seen take an order from a student before, swept his belled hat from his head and sprang to a salute as Fred and George wheeled about to tumultuous applause from the students below and sped out of the open front doors into the glorious sunset.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:275},{id:"movies-417",text:"You have to wonder: how do the machines know what Tasty Wheat tasted like? Maybe they got it wrong. Maybe what I think Tasty Wheat tasted like actually tasted like oatmeal, or tuna fish. That makes you wonder about a lot of things. You take chicken, for example: maybe they couldn't figure out what to make chicken taste like, which is why chicken tastes like everything.",author:"",source:"The Matrix",category:"movies",license:"Fair Use",difficulty:"hard",length:371},{id:"movies-418",text:"Listen up, maggots. You are not special. You are not a beautiful or unique snowflake. You're the same decaying organic matter as everything else.",author:"",source:"Fight Club",category:"movies",license:"Fair Use",difficulty:"medium",length:145},{id:"movies-419",text:"A heart is not judged by how much you love but by how much you are loved by others.",author:"",source:"The Wizard of Oz",category:"movies",license:"Fair Use",difficulty:"medium",length:83},{id:"movies-420",text:"Death is irrelevant. Your archaic cultures are authority driven. To facilitate our introduction into your societies, it has been decided that a human voice will speak for us in all communications. You have been chosen to be that voice.",author:"",source:"Star Trek",category:"movies",license:"Fair Use",difficulty:"hard",length:235},{id:"movies-421",text:"We're so glad to see so many of you lovely people here tonight. And we would especially like to welcome all the representatives of Illinois's law enforcement community who have chosen to join us here in the Palace Hotel Ballroom at this time. We certainly hope you all enjoy the show. And remember, people, that no matter who you are and what you do to live, thrive and survive, there's still some things that make us all the same. You. Me. Them. Everybody. Everybody.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:468},{id:"movies-422",text:"Haven't I taught you anything? What have I always told you? Never trust anything that can think for itself if you can't see where it keeps its brain?",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"medium",length:149},{id:"movies-423",text:"I don't like sand. It's coarse and rough and irritating and it gets everywhere. Not like here. Here everything is soft and smooth.",author:"",source:"Star Wars",category:"movies",license:"Fair Use",difficulty:"medium",length:130},{id:"movies-424",text:"The more stupid one is, the closer one is to reality. The more stupid one is, the clearer one is. Stupidity is brief and artless, while intelligence squirms and hides itself. Intelligence is unprincipled, but stupidity is honest and straightforward.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:249},{id:"movies-425",text:"The mystery of human existence lies not in just staying alive, but in finding something to live for.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:100},{id:"movies-426",text:"Oceans apart day after day and I slowly go insane. I hear your voice on the line but it doesn't stop the pain. If I see you next to never how can we say forever?",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:161},{id:"movies-427",text:"I'm going to improvise. Listen, there's something you should know about me... about inception. An idea is like a virus, resilient, highly contagious. The smallest seed of an idea can grow. It can grow to define or destroy you.",author:"",source:"Inception",category:"movies",license:"Fair Use",difficulty:"hard",length:226},{id:"movies-428",text:"The term First Contact applies to the moment when we employ a means of communication with alien beings that also have a means of talking back to us. There are several ways First Contact could happen. The most popular idea, originating from the UFO phenomenon, is the image of ET landing on the lawn of the White House and greeting the president. However, scientists hope they are the first to establish communication with ET, via radio signals.",author:"",source:"Alien",category:"movies",license:"Fair Use",difficulty:"hard",length:444},{id:"movies-429",text:"In the beginning there was discovery. A confusion of elements. The first snowfall of impossible change. Old lives undone, left behind. Strange faces, made familiar. New nightmares, to challenge sleep. New friends, to feel safe with. Only then comes control. The need to impose order unto chaos, through determination, through study, through struggle. All in defiance of a thundering truth. They're here, and the earth shudders underfoot.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:437},{id:"movies-430",text:"Well, Mr. Gardner, I must admit that is one of the most refreshing and optimistic statements I've heard in a very, very long time. I admire your good, solid sense. That's precisely what we lack on Capitol Hill.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:210},{id:"movies-431",text:"Why, if I had a brain I could... I could while away the hours, conferrin' with the flowers, consultin' with the rain. And my head I'd be scratchin' while my thoughts were busy hatchin' if I only had a brain.",author:"",source:"The Wizard of Oz",category:"movies",license:"Fair Use",difficulty:"hard",length:207},{id:"movies-432",text:"I've got to get up in the morning and spend some more money on my overpriced education.",author:"",source:"Good Will Hunting",category:"movies",license:"Fair Use",difficulty:"medium",length:87},{id:"movies-433",text:"I'm singin' in the rain, just singin' in the rain. What a glorious feeling, I'm happy again. I'm laughin' at clouds, so dark up above. The sun's in my heart, and I'm ready for love.",author:"",source:"Singin' in the Rain",category:"movies",license:"Fair Use",difficulty:"hard",length:181},{id:"movies-434",text:`You know what kind of plan never fails? No plan at all. No plan. You know why? If you make a plan, life never works out that way. Look around us, did these people think "Let's all spend the night in a gym?" But look now, everyone's sleeping on the floor, us included. That's why people shouldn't make plans. With no plan, nothing can go wrong and if something spins out of control, it doesn't matter. Whether you kill someone or betray your country. None of it matters. Got it?`,author:"",source:"Parasite",category:"movies",license:"Fair Use",difficulty:"hard",length:477},{id:"movies-435",text:"Do you know why you're not afraid to die, Spock? You're more afraid of living. Each day you stay alive is just one more day you might slip and let your human half peek out. That's it, isn't it? Insecurity. Why, you wouldn't know what to do with a genuine, warm, decent feeling.",author:"",source:"Star Trek",category:"movies",license:"Fair Use",difficulty:"hard",length:277},{id:"movies-436",text:"Mac knew the score even if Aunt Ella didn't. Shot through the left lung and that was that, as they say. Believe it was that night. She buried him the next mornin'. Diggin' in that hard caliche. What you got ain't nothin' new. This country is hard on people. Hard and crazy. Got the devil in it yet folks never seem to hold it to account.",author:"",source:"No Country for Old Men",category:"movies",license:"Fair Use",difficulty:"hard",length:337},{id:"movies-437",text:"All right, if this guy just took advantage of a natural accident to sell me twenty-four cans of nothing, I'm going to applaud his creative entrepreneurial spirit and then kill him.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:180},{id:"movies-438",text:`Lieutenant Dan got me invested in some kind of fruit company. So then I got a call from him, saying we don't have to worry about money no more. And I said, "That's good! One less thing."`,author:"",source:"Forrest Gump",category:"movies",license:"Fair Use",difficulty:"hard",length:186},{id:"movies-439",text:"October arrived, spreading a damp chill over the grounds and into the castle. Madam Pomfrey, the nurse, was kept busy by a sudden spate of colds among the staff and students.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:174},{id:"movies-440",text:"What I'm trying to teach him and what he's learning there are two very different things. Park hustlers play tactics, not position. They rely on wild, unpredictable moves meant to intimidate their opponent. Great in a two-minute speed game for drug money, but it'll cost Josh dearly in real games.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:296},{id:"movies-441",text:"Oh, no, sir. I'm sorry, sir. I could never answer to a whistle. Whistles are for dogs and cats and other animals, but not for children and definitely not for me. It would be too humiliating.",author:"",source:"The Sound of Music",category:"movies",license:"Fair Use",difficulty:"hard",length:190},{id:"movies-442",text:"The Aurors are part of the Rotfang Conspiracy, I thought everyone knew that. They're working from within to bring down the Ministry of Magic with a combination of dark magic and gum disease.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:190},{id:"movies-443",text:`We generally concur that "men" such as a cow, a turkey, a frog, and a fish all possess some spark of consciousness, some kind of primitive "soul" but by God, it's a good deal smaller than ours is - and that, no more and no less, is why we "men" feel that we have the perfect right to extinguish the dim lights in the heads of these fractionally-souled beasts and to gobble down their once warm and wiggling, now chilled and stilled protoplasm with limitless gusto, and not feel a trace of guilt while doing so.`,author:"Gödel",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:510},{id:"movies-444",text:"Hokey religions and ancient weapons are no match for a good blaster at your side, kid.",author:"",source:"Star Wars",category:"movies",license:"Fair Use",difficulty:"medium",length:86},{id:"movies-445",text:"This little droid. I think he's searching for his former master. I've never seen such devotion in a droid before. Ah, he claims to be the property of an Obi-Wan Kenobi. Is he a relative of yours? Do you know what he's talking about?",author:"",source:"Star Wars",category:"movies",license:"Fair Use",difficulty:"hard",length:232},{id:"movies-446",text:"Morphic resonance is a process whereby self-organising systems inherit a memory from previous similar systems. In its most general formulation, morphic resonance means that the so-called laws of nature are more like habits. The hypothesis of morphic resonance also leads to a radically new interpretation of memory storage in the brain and of biological inheritance.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:366},{id:"movies-447",text:"No, I thought not. You have not asked me for instance, what is my favorite jam, to check that I am not an impostor. For future reference, Harry, it is raspberry... although of course, if I were a Death Eater, I would have been sure to find out my own jam preferences before impersonating myself.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:295},{id:"movies-448",text:"You know, Marty, I'm gonna be very sad to see you go. You've really made a difference in my life. You've given me something to shoot for. Just knowing that I'm going to be around to see 1985. That I'm gonna succeed in this! That I'm gonna have a chance to travel through time!",author:"",source:"Back to the Future",category:"movies",license:"Fair Use",difficulty:"hard",length:276},{id:"movies-449",text:"All right, I'll go in there for Dorothy. Wicked Witch or no Wicked Witch, guards or no guards, I'll tear them apart. I may not come out alive, but I'm going in there. There's only one thing I want you fellows to do. Talk me out of it!",author:"",source:"The Wizard of Oz",category:"movies",license:"Fair Use",difficulty:"hard",length:234},{id:"movies-450",text:"Here, take a cookie. I promise, by the time you're done eating it, you'll feel right as rain.",author:"",source:"The Matrix",category:"movies",license:"Fair Use",difficulty:"medium",length:93},{id:"movies-451",text:"I want to speak to someone in charge. I want to lodge a complaint. You have no right to make people crazy! You think I investigate every Walter Cronkite story there is? Huh? If this is just nerve gas, how come I know everything in such detail? I've never been here before. How come I know so much?",author:"",source:"Close Encounters of the Third Kind",category:"movies",license:"Fair Use",difficulty:"hard",length:297},{id:"movies-452",text:"Since, as is well known, God helps those who help themselves, presumably the Devil helps all those, and only those, who don't help themselves. Does the Devil help himself?",author:"Gödel",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:171},{id:"movies-453",text:"Mac, they said you escaped. I knew you wouldn't leave without me. I was waiting for you. Now we can make it, Mac. I feel big as a damn mountain. Oh, no. I'm not goin' without you, Mac. I wouldn't leave you this way. You're coming with me. Let's go.",author:"",source:"One Flew Over the Cuckoo's Nest",category:"movies",license:"Fair Use",difficulty:"hard",length:248},{id:"movies-454",text:"In the early days of computer chess people used to estimate that it would be ten years until a computer (or program) was world champion. But after ten years had passed, it seemed that the day a computer would become world champion was still more than ten years away... This is just one more piece of evidence for the rather recursive Hofstadter's Law: It always takes longer than you expect, even when you take into account Hofstadter's Law.",author:"Gödel",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:441},{id:"movies-455",text:"Then Valdr showed them a nest of sleeping starlings, and Eragon could feel their dreams flickering in their minds, fast as the blink of an eye. At first Valdr's emotion was one of contempt - the starlings' dreams seemed tiny, petty, and inconsequential - but then his mood changed and became warm and sympathetic, and even the smallest of the starlings' concerns grew in importance until it seemed equal to the worries of kings.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:428},{id:"movies-456",text:"Mr. and Mrs. Dursley, of number four, Privet Drive, were proud to say that they were perfectly normal, thank you very much. They were the last people you'd expect to be involved in anything strange or mysterious, because they just didn't hold with such nonsense.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:262},{id:"movies-457",text:`You see, I feel sorrier for you than I do for him. Because you'll never know the things that love can drive a man to. The ecstasies, the miseries. The broken rules. The desperate chances. The glorious failures and the glorious victories. All of these things you'll never know simply because the word "love" isn't written into your book.`,author:"",source:"Star Trek",category:"movies",license:"Fair Use",difficulty:"hard",length:336},{id:"movies-458",text:"Get it straight buster - I'm not here to say please, I'm here to tell you what to do and if self-preservation is an instinct you possess you'd better do it and do it quick! I'm here to help - if my help is not appreciated then lots of luck, gentlemen.",author:"",source:"Pulp Fiction",category:"movies",license:"Fair Use",difficulty:"hard",length:251},{id:"movies-459",text:"As customers of all races, nationalities, and cultures visit the Dekalb Farmers Market by the thousands, I doubt that many stand in awe and contemplate the meaning of its existence. But in the capital of the Sunbelt South, the quiet revolution of immigration and food continues to upset and redefine the meanings of local, regional, and global identity.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:353},{id:"movies-460",text:"As a child, I was aware that, at night, infrared vision would reveal monsters hiding in the bedroom closet only if they were warm-blooded. But everybody knows that your average bedroom monster is reptilian and cold-blooded.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:223},{id:"movies-461",text:"The consequences of our actions are always so complicated, so diverse, that predicting the future is a very difficult business indeed.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"medium",length:134},{id:"movies-462",text:"And it's a happy ending. Wayward husband comes to his senses, returns to his wife, with whom he has established a long and sustaining love. Heartless young woman left alone in her arctic desolation. Music up with a swell; final commercial. And here are a few scenes from next week's show.",author:"",source:"Network",category:"movies",license:"Fair Use",difficulty:"hard",length:288},{id:"movies-463",text:"You can have my answer now, if you like. My final offer is this: nothing. Not even the fee for the gaming license, which I would appreciate if you would put up personally.",author:"",source:"The Godfather",category:"movies",license:"Fair Use",difficulty:"hard",length:171},{id:"movies-464",text:"It was close upon four before the door opened, and a drunken-looking groom, ill-kempt and side-whiskered, with an inflamed face and disreputable clothes, walked into the room. Accustomed as I was to my friend's amazing powers in the use of disguises, I had to look three times before I was certain that it was indeed he. With a nod he vanished into the bedroom, whence he emerged in five minutes tweed-suited and respectable, as of old. Putting his hands into his pockets, he stretched out his legs in front of the fire and laughed heartily for some minutes.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:558},{id:"movies-465",text:'String theory, which posits that all the forces of nature stem from stringy thingies wriggling in nine or more dimensions, implies that our cosmos is just a hillock in a sprawling "landscape" of universes, some with radically different laws and dimensions than ours. Chaotic inflation, a supercharged version of the big bang theory, suggests that our universe is a minuscule bubble in a boundless, frothy sea.',author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:409},{id:"movies-466",text:"Now Lina, you've been reading all those fan magazines again! Now look Lina, you shouldn't believe all that banana oil Dora Bailey and the columnists dish out. Now try to get this straight: there is nothing between us. There has never been anything between us. Just air.",author:"",source:"Singin' in the Rain",category:"movies",license:"Fair Use",difficulty:"hard",length:269},{id:"movies-467",text:"Ladies and gentlemen, this is a flying saucer. It's made of pewter, made in Japan, and thrown across the lawn by one of my children. I just wanted to point that out to you to show that we're not all polished brass about these things. Also to make a point that last year Americans shot more than seven billion photographs at a record of 6.6 billion dollars for film, equipment, and processing. Now with all those shutters clicking where is the indisputable photographic evidence?",author:"",source:"Close Encounters of the Third Kind",category:"movies",license:"Fair Use",difficulty:"hard",length:478},{id:"movies-468",text:"I hope you're pleased with yourselves. We could all have been killed - or worse, expelled. Now if you don't mind, I'm going to bed.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:131},{id:"movies-469",text:"It does not do well to dwell on dreams and forget to live.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"easy",length:58},{id:"movies-470",text:"To the well-organized mind, death is but the next great adventure.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"easy",length:66},{id:"movies-471",text:"You're a little scary sometimes, you know that? Brilliant... but scary.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"easy",length:71},{id:"movies-472",text:"There will be no foolish wand-waving or silly incantations in this class. As such, I don't expect many of you to appreciate the subtle science and exact art that is potion-making. However, for those select few who possess the predisposition, I can teach you how to bewitch the mind and ensnare the senses. I can tell you how to bottle fame, brew glory, and even put a stopper in death. Then again, maybe some of you have come to Hogwarts in possession of abilities so formidable that you feel confident enough to not pay attention!",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:531},{id:"movies-473",text:"There are all kinds of courage, said Dumbledore, smiling. It takes a great deal of bravery to stand up to our enemies, but just as much to stand up to our friends.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:163},{id:"movies-474",text:"The truth. It is a beautiful and terrible thing, and should therefore be treated with great caution.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:100},{id:"movies-475",text:"There are some things you can't share without ending up liking each other, and knocking out a twelve-foot mountain troll is one of them.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:136},{id:"movies-476",text:'"Ah, music," he said, wiping his eyes. "A magic beyond all we do here!"',author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"easy",length:71},{id:"movies-477",text:"I solemnly swear that I am up to no good.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"easy",length:41},{id:"movies-478",text:`Honestly, am I the only person who's ever bothered to read "Hogwarts: A History?"`,author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"medium",length:81},{id:"movies-479",text:"If you want to know what a man's like, take a good look at how he treats his inferiors, not his equals.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"medium",length:103},{id:"movies-480",text:"It matters not what someone is born, but what they grow to be.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"easy",length:62},{id:"movies-481",text:"We are only as strong as we are united, as weak as we are divided.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"easy",length:66},{id:"movies-482",text:"Your devotion is nothing more than cowardice. You would not be here if you had anywhere else to go.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"medium",length:99},{id:"movies-483",text:"Numbing the pain for a while will make it worse when you finally feel it.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"easy",length:73},{id:"movies-484",text:"Anyone can speak Troll. All you have to do is point and grunt.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"easy",length:62},{id:"movies-485",text:"Curiosity is not a sin... But we should exercise caution with our curiosity... yes, indeed.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"medium",length:91},{id:"movies-486",text:"Just because it's taken you three years to notice, Ron, doesn't mean no one else has spotted I'm a girl!",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"medium",length:104},{id:"movies-487",text:"Differences of habit and language are nothing at all if our aims are identical and our hearts are open.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"medium",length:103},{id:"movies-488",text:"I think we've outgrown full-time education... Time to test our talents in the real world, d'you reckon?",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"medium",length:103},{id:"movies-489",text:"Harry witnessed Professor McGonagall walking right past Peeves who was determinedly loosening a crystal chandelier and could have sworn he heard her tell the poltergeist out of the corner of her mouth, 'It unscrews the other way.'",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:230},{id:"movies-490",text:"I think I'll just go down and have some pudding and wait for it all to turn up - it always does in the end.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"medium",length:107},{id:"movies-491",text:"Just because you have the emotional range of a teaspoon doesn't mean we all have.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"medium",length:81},{id:"movies-492",text:"You can laugh, but people used to believe there were no such things as the Blibbering Humdinger or the Crumple-Horned Snorkack!",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"medium",length:127},{id:"movies-493",text:"I mean, it's sort of exciting, isn't it, breaking the rules?",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"easy",length:60},{id:"movies-494",text:"Indifference and neglect often do much more damage than outright dislike.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"easy",length:73},{id:"movies-495",text:"Youth can not know how age thinks and feels. But old men are guilty if they forget what it was to be young.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"medium",length:107},{id:"movies-496",text:"Things we lose have a way of coming back to us in the end, if not always in the way we expect.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"medium",length:94},{id:"movies-497",text:"Wit beyond measure is man's greatest treasure.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"easy",length:46},{id:"movies-498",text:"The thing about growing up with Fred and George is that you sort of start thinking anything's possible if you've got enough nerve.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"medium",length:130},{id:"movies-499",text:"And now, Harry, let us step out into the night and pursue that flighty temptress, adventure.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"medium",length:92},{id:"movies-500",text:"Dumbledore says people find it far easier to forgive others for being wrong than being right.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"medium",length:93},{id:"movies-501",text:"Age is foolish and forgetful when it underestimates youth.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"easy",length:58},{id:"movies-502",text:"Once again, you show all the sensitivity of a blunt axe.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"easy",length:56},{id:"movies-503",text:"It is the unknown we fear when we look upon death and darkness, nothing more.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"easy",length:77},{id:"movies-504",text:`"No, Harry, you listen," said Hermione. "We're coming with you. That was decided months ago - years, really."`,author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"medium",length:109},{id:"movies-505",text:"'That wand's more trouble than it's worth,' said Harry. 'And quite honestly,' he turned away from the painted portraits, thinking now only of the four-poster bed lying waiting for him in Gryffindor Tower, and wondering whether Kreacher might bring him a sandwich there, 'I've had enough trouble for a lifetime.'",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"hard",length:311},{id:"movies-506",text:"Every human life is worth the same, and worth saving.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"easy",length:53},{id:"movies-507",text:"Words are, in my not-so-humble opinion, our most inexhaustible source of magic. Capable of both inflicting injury, and remedying it.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"medium",length:132},{id:"movies-508",text:"Of course it is happening inside your head, Harry, but why on Earth should that mean that it is not real?",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"medium",length:105},{id:"movies-509",text:"I know you're out there. I can feel you now. I know that you're afraid... you're afraid of us. You're afraid of change. I don't know the future. I didn't come here to tell you how this is going to end. I came here to tell you how it's going to begin. I'm going to hang up this phone, and then I'm going to show these people what you don't want them to see. I'm going to show them a world without you. A world without rules and controls, without borders or boundaries. A world where anything is possible. Where we go from there is a choice I leave to you...",author:"Neo",source:"The Matrix",category:"movies",license:"Fair Use",difficulty:"hard",length:556},{id:"movies-510",text:"In one life you're Thomas A. Anderson, program writer for a respectable software company. You have a social security number; you pay your taxes; and you help your landlady carry out her garbage.",author:"Agent Smith",source:"The Matrix",category:"movies",license:"Fair Use",difficulty:"hard",length:194},{id:"movies-511",text:"You know, I know this steak doesn't exist. I know that when I put it in my mouth, the Matrix is telling my brain that it is juicy and delicious. After nine years, you know what I realize? Ignorance is bliss.",author:"Cypher",source:"The Matrix",category:"movies",license:"Fair Use",difficulty:"hard",length:207},{id:"movies-512",text:"Throughout human history, we have been dependent on machines to survive. Fate, it seems, is not without a sense of irony.",author:"Morpheus",source:"The Matrix",category:"movies",license:"Fair Use",difficulty:"medium",length:121},{id:"movies-513",text:"What are you waiting for? You're faster than this. Don't think you are, know you are. Come on, stop trying to hit me, and hit me!",author:"Morpheus",source:"The Matrix",category:"movies",license:"Fair Use",difficulty:"medium",length:129},{id:"movies-514",text:"If real is what you can feel, smell, taste and see, then 'real' is simply electrical signals interpreted by your brain.",author:"Morpheus",source:"The Matrix",category:"movies",license:"Fair Use",difficulty:"medium",length:119},{id:"movies-515",text:"Were you listening to me, Neo? Or were you looking at the woman in the red dress?",author:"Morpheus",source:"The Matrix",category:"movies",license:"Fair Use",difficulty:"medium",length:81},{id:"movies-516",text:"There are always a few such people who demand the utmost of life and yet cannot come to terms with its stupidity and crudeness.",author:"Hermann Hesse",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:127},{id:"movies-517",text:"Have you ever had a dream, Neo, that you seemed so sure it was real? But if you were unable to wake from that dream, how would you tell the difference between the dream world and the real world?",author:"Morpheus",source:"The Matrix",category:"movies",license:"Fair Use",difficulty:"hard",length:194},{id:"movies-518",text:"The music is not in the notes, but in the silence in between.",author:"",source:"Amadeus",category:"movies",license:"Fair Use",difficulty:"easy",length:61},{id:"movies-519",text:"The Dursleys had everything they wanted, but they also had a secret, and their greatest fear was that somebody would discover it.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:129},{id:"movies-520",text:"Pride is not the opposite of shame, but its source. True humility is the only antidote to shame.",author:"",source:"Avatar",category:"movies",license:"Fair Use",difficulty:"medium",length:96},{id:"movies-521",text:"My first girlfriend turned into the moon... That's rough, buddy.",author:"",source:"Avatar",category:"movies",license:"Fair Use",difficulty:"easy",length:64},{id:"movies-522",text:"You sound like my nephew, always thinking you need to do things on your own without anyone's support. There is nothing wrong with letting the people who love you help you.",author:"",source:"Avatar",category:"movies",license:"Fair Use",difficulty:"hard",length:171},{id:"movies-523",text:"One and one and one is three.",author:"The Beatles",source:"Her",category:"movies",license:"Fair Use",difficulty:"easy",length:29},{id:"movies-524",text:"You can't hang around waiting for somebody else to pull your strings. Destiny's what you make of it. You have to face whatever life throws at you. And if it throws more than you'd like, more than you think you can handle? Well then you just have to find the heroism within yourself and play out the hand you've been dealt. The universe never sets a challenge that can't be met. You just need to believe in yourself in order to find the strength to face it.",author:"Darren Shan",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:456},{id:"movies-525",text:"Now, if you two don't mind I'll be off to bed before either of you come up with another clever idea to get us killed - or worse, expelled!",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:138},{id:"movies-526",text:"The County Weather Service has issued a warning for a meteorological event. This warning is effective immediately and continues until sunrise tomorrow morning. Citizens are advised not to observe this event with the naked eye.",author:"LOCAL58TV",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:226},{id:"movies-527",text:"Do not pity the dead, Harry. Pity the living and above all, those who live without love.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"medium",length:88},{id:"movies-528",text:"An ideal is only an ideal after all. As long as you embrace that ideal, the friction with reality will continue to increase. So you will someday face reality and will have to pay the price for your compromises.",author:"Archer",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:210},{id:"movies-529",text:"When dreams become more important than reality, you give up travel, building, creating; you even forget how to repair the machines left behind by your ancestors. You just sit living and reliving other lives left behind in the thought records.",author:"",source:"Star Trek",category:"movies",license:"Fair Use",difficulty:"hard",length:242},{id:"movies-530",text:`Genius doesn't work on an assembly line basis. Did Einstein, Kazanga or Sitar of Vulcan produce new and revolutionary theories on a regular schedule? You can't simply say, "Today I will be brilliant."`,author:"",source:"Star Trek",category:"movies",license:"Fair Use",difficulty:"hard",length:200},{id:"movies-531",text:"I speak of rights! A machine has none; a man must. If you do not grant him that right, you have brought us down to the level of the machine; indeed, you have elevated that machine above us!",author:"",source:"Star Trek",category:"movies",license:"Fair Use",difficulty:"hard",length:189},{id:"movies-532",text:"Human beings do not survive on bread alone... but on the nourishments of liberty. For what indeed is a man without freedom... naught but a mechanism, trapped in the cogwheels of eternity.",author:"",source:"Star Trek",category:"movies",license:"Fair Use",difficulty:"hard",length:187},{id:"movies-533",text:"Your will to survive, your love of life, your passion to know... Everything that is truest and best in all species of beings has been revealed to you. Those are the qualities that make a civilization worthy to survive.",author:"",source:"Star Trek",category:"movies",license:"Fair Use",difficulty:"hard",length:218},{id:"movies-534",text:"Now, I don't pretend to tell you how to find happiness and love, when every day is a struggle to survive. But I do insist that you do survive, because the days and the years ahead are worth living for!",author:"",source:"Star Trek",category:"movies",license:"Fair Use",difficulty:"hard",length:201},{id:"movies-535",text:"With the first link, the chain is forged. The first speech censored, the first thought forbidden, the first freedom denied, chains us all irrevocably.",author:"",source:"Star Trek",category:"movies",license:"Fair Use",difficulty:"hard",length:150},{id:"movies-536",text:"Our species can only survive if we have obstacles to overcome. You remove those obstacles. Without them to strengthen us, we will weaken and die.",author:"",source:"Star Trek",category:"movies",license:"Fair Use",difficulty:"medium",length:145},{id:"movies-537",text:"You know the greatest danger facing us is ourselves, and irrational fear of the unknown. There is no such thing as the unknown. Only things temporarily hidden, temporarily not understood.",author:"",source:"Star Trek",category:"movies",license:"Fair Use",difficulty:"hard",length:187},{id:"movies-538",text:"You may find that having is not so pleasing a thing as wanting. This is not logical, but it is often true.",author:"",source:"Star Trek",category:"movies",license:"Fair Use",difficulty:"medium",length:106},{id:"movies-539",text:"I can't erase all the things that I've done, but all the mistakes made me who I've become.",author:"Fletcher",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:90},{id:"movies-540",text:"You either die a hero, or you live long enough to see yourself become the villain.",author:"",source:"The Dark Knight",category:"movies",license:"Fair Use",difficulty:"medium",length:82},{id:"movies-541",text:"I guess you guys aren't ready for that yet. But your kids are gonna love it.",author:"",source:"Back to the Future",category:"movies",license:"Fair Use",difficulty:"easy",length:76},{id:"movies-542",text:"Their morals, their code; it's a bad joke. Dropped at the first sign of trouble. They're only as good as the world allows them to be. You'll see. I'll show you. When the chips are down these, uh, civilized people? They'll eat each other. See I'm not a monster, I'm just ahead of the curve.",author:"",source:"The Dark Knight",category:"movies",license:"Fair Use",difficulty:"hard",length:289},{id:"movies-543",text:"Did you ever hear the tragedy of Darth Plagueis The Wise? I thought not. It's not a story the Jedi would tell you. It's a Sith legend. Darth Plagueis was a Dark Lord of the Sith, so powerful and so wise he could use the Force to influence the midichlorians to create life... He had such a knowledge of the dark side that he could even keep the ones he cared about from dying. The dark side of the Force is a pathway to many abilities some consider to be unnatural. He became so powerful... the only thing he was afraid of was losing his power, which eventually, of course, he did. Unfortunately, he taught his apprentice everything he knew, then his apprentice killed him in his sleep. Ironic. He could save others from death, but not himself.",author:"",source:"Star Wars",category:"movies",license:"Fair Use",difficulty:"hard",length:743},{id:"movies-544",text:"Once you've met someone, you never really forget them. It just takes a while for your memories to return.",author:"",source:"Spirited Away",category:"movies",license:"Fair Use",difficulty:"medium",length:105},{id:"movies-545",text:"Well, dreams, they feel real while we're in them right? It's only when we wake up that we realize that something was actually strange.",author:"",source:"Inception",category:"movies",license:"Fair Use",difficulty:"medium",length:134},{id:"movies-546",text:"He's the hero Gotham deserves, but not the one it needs right now. So, we'll hunt him, because he can take it. Because he's not our hero. He's a silent guardian. A watchful protector. A Dark Knight.",author:"",source:"The Dark Knight",category:"movies",license:"Fair Use",difficulty:"hard",length:198},{id:"movies-547",text:"It's only after we've lost everything that we're free to do anything.",author:"",source:"Fight Club",category:"movies",license:"Fair Use",difficulty:"easy",length:69},{id:"movies-548",text:"In times of crisis, the wise build bridges while the foolish build barriers.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"easy",length:76},{id:"movies-549",text:"I was rushing desperately, trying to reach the light. When I thought I did, I reached a dead end instead. Then I decided I wanted to enter that light. And at the edge of it, I found you.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:186},{id:"movies-550",text:"The human mind works in mysterious ways. You just need to see the sun shining in the morning to feel energized. A blue sky makes you feel happy you're alive.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:157},{id:"movies-551",text:"God, if you really exist, then I beg you. This is more than enough. I don't need anything else. We'll manage somehow. So please. Don't throw anything more at us. But don't take anything more from us either. I'm begging you. Please, God. I want to stay like this. Together. Forever and ever.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:290},{id:"movies-552",text:"Listen. Just because you have psychic powers, it doesn't make you any less human. It's the same as people who are fast, people who are book smart, and people with strong body odor. Psychic powers are just another characteristic. You must embrace that as a part of yourself and continue to live positively. The truth behind one's charm is kindness. Become a good person. That is all.",author:"",source:"Psycho",category:"movies",license:"Fair Use",difficulty:"hard",length:382},{id:"movies-553",text:"Sometimes I feel like I've already seen everything that's gonna happen and it's a nightmare.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:92},{id:"movies-554",text:"Sometimes I feel like love doesn't actually exist. It's just pheromones playing tricks on people.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:97},{id:"movies-555",text:"In the rigor which is space, this spacesuit was designed by engineers to maintain your life in space, and can be called the smallest spaceship.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:143},{id:"movies-556",text:"People have an annoying habit of remembering things they shouldn't.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"easy",length:67},{id:"movies-557",text:"Books are my friends, my companions. They make me laugh and cry and find meaning in life.",author:"Jeod",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:89},{id:"movies-558",text:"It's the ship that made the Kessel run in less than twelve parsecs. I've outrun Imperial starships. Not the local bulk cruisers, mind you. I'm talking about the big Corellian ships, now. She's fast enough for you, old man.",author:"",source:"Star Wars",category:"movies",license:"Fair Use",difficulty:"hard",length:222},{id:"movies-559",text:"Everyone is here, but you're nowhere near. No, you're nowhere near.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"easy",length:67},{id:"movies-560",text:"I look around, I look around, I see a lot of new faces. Which means a lot of people have been breaking the first two rules of Fight Club. Man, I see in fight club the strongest and smartest men who've ever lived. I see all this potential, and I see squandering. God damn it, an entire generation pumping gas, waiting tables; slaves with white collars. Advertising has us chasing cars and clothes, working jobs we hate so we can buy crap we don't need. We're the middle children of history, man. No purpose or place. We have no Great War. No Great Depression. Our Great War's a spiritual war. Our Great Depression is our lives. We've all been raised on television to believe that one day we'd all be millionaires, and movie gods, and rockstars. But we won't. And we're slowly learning that fact. And we're very, very pissed off.",author:"",source:"Fight Club",category:"movies",license:"Fair Use",difficulty:"hard",length:827},{id:"movies-561",text:"Oh, brother, we go deeper than the ink beneath the skin of our tattoos. Though we don't share the same blood, you're my brother and I love you, that's the truth.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:161},{id:"movies-562",text:"Star in your eyes, sun in your smile, the way you look at me - it makes me hum and I call it love song.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:103},{id:"movies-563",text:`That, to me, is an absolute tragedy. But that's just what the world wants now. People wonder why jazz is dying. I tell you, man, and every Starbucks "jazz" album... just proves my point really. There are no two words in the English language more harmful than "good job."`,author:"",source:"Whiplash",category:"movies",license:"Fair Use",difficulty:"hard",length:270},{id:"movies-564",text:"There is an idea of a Patrick Bateman, some kind of abstraction, but there is no real me, only an entity, something illusory, and though I can hide my cold gaze and you can shake my hand and feel flesh gripping yours and maybe you can even sense our lifestyles are probably comparable: I simply am not there.",author:"",source:"Psycho",category:"movies",license:"Fair Use",difficulty:"hard",length:308},{id:"movies-565",text:"I laugh maniacally, then take a deep breath and touch my chest - expecting a heart to be thumping quickly, impatiently, but there's nothing there, not even a beat.",author:"",source:"Psycho",category:"movies",license:"Fair Use",difficulty:"hard",length:163},{id:"movies-566",text:"The dark side of the Force is a pathway to many abilities some consider to be unnatural.",author:"",source:"Star Wars",category:"movies",license:"Fair Use",difficulty:"medium",length:88},{id:"movies-567",text:"This is Master Obi-Wan Kenobi. I regret to report that both the Jedi and the Republic have fallen, with the dark shadow of the Empire rising to take their place. This message is a warning and a reminder for any surviving Jedi: Trust in the force. Do not return to the Temple. That time has passed, and our future is uncertain. We will each be challenged. Our trust. Our faith. Our friendship. But we must persevere and in time a new hope will emerge. May the force be with you. Always.",author:"",source:"Star Wars",category:"movies",license:"Fair Use",difficulty:"hard",length:485},{id:"movies-568",text:"Is there a problem with Earth's gravitational pull in the future? Why is everything so heavy?",author:"",source:"Back to the Future",category:"movies",license:"Fair Use",difficulty:"medium",length:93},{id:"movies-569",text:"You could just write your own rules. You know, write something that's as interesting as you are.",author:"",source:"La La Land",category:"movies",license:"Fair Use",difficulty:"medium",length:96},{id:"movies-570",text:`My momma always said, "Life was like a box of chocolates. You never know what you're gonna get."`,author:"",source:"Forrest Gump",category:"movies",license:"Fair Use",difficulty:"medium",length:96},{id:"movies-571",text:`You don't listen, do you? I don't think you ever really hear me. You just ask the same questions every week. "How's your job?" "Are you having any negative thoughts?" All I have are negative thoughts.`,author:"",source:"Joker",category:"movies",license:"Fair Use",difficulty:"hard",length:200},{id:"movies-572",text:"That's what the Emperor said. A man steals something, he's brought in before the Emperor, he throws himself down on the ground. He begs for his life, he knows he's going to die. And the Emperor... pardons him. This worthless man, he lets him go.",author:"",source:"Schindler's List",category:"movies",license:"Fair Use",difficulty:"hard",length:245},{id:"movies-573",text:"My father was fond of saying you need three things in life - a good doctor, a forgiving priest, and a clever accountant. The first two, I've never had much use for.",author:"",source:"Schindler's List",category:"movies",license:"Fair Use",difficulty:"hard",length:164},{id:"movies-574",text:`Dude... where's your suit? Just once, when I say "suit up" I wish you'd put on a suit.`,author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:86},{id:"movies-575",text:"A lie is just a great story that someone ruined with the truth.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"easy",length:63},{id:"movies-576",text:"You see, kids, right from the moment I met your mom I knew, I have to love this woman as much as I can, and as long as I can, and I can never stop loving her, not even for a second.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:181},{id:"movies-577",text:"A word of advice: Play along. The more you fight it, the worse it's gonna get.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"easy",length:78},{id:"movies-578",text:"Sometimes things have to fall apart to make way for better things.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"easy",length:66},{id:"movies-579",text:"It's only once you've stopped that you realize how hard it is to start again.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"easy",length:77},{id:"movies-580",text:"We're going to get older, whether we like it or not, so the only question is whether we get on with our lives or desperately cling to the past.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:143},{id:"movies-581",text:"Never underestimate the power of destiny. Because when you least expect it, the littlest thing can cause a ripple effect that changes your life.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:144},{id:"movies-582",text:"Here's the thing about mistakes: Sometimes, even when you know something's a mistake, you gotta make it anyway.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:111},{id:"movies-583",text:"You see, the universe has a plan, kids, and that plan is always in motion.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"easy",length:74},{id:"movies-584",text:"Sometimes our best decisions are the ones that don't make sense at all.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"easy",length:71},{id:"movies-585",text:"If you keep giving up on people so quickly, you're gonna miss out on something great.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:85},{id:"movies-586",text:"I get recognized one time, and I start thinking I'm Julia Roberts. I'm no VIP; I'm not even an IP; I'm just a lonely little P sitting out here in the gutter.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:157},{id:"movies-587",text:"Destined? Aren't you tired of waiting for destiny, Ted? Isn't it time to make your own destiny?",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:95},{id:"movies-588",text:"I don't know where I'm gonna be in five years. I don't wanna know. I want my life to be an adventure.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:101},{id:"movies-589",text:"It's just, eventually we're all gonna move on. It's called growing up.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"easy",length:70},{id:"movies-590",text:"You can't just skip ahead to where you think your life should be.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"easy",length:65},{id:"movies-591",text:"The three-day rule is a childish, manipulative mind game. But yeah, you wait three days.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:88},{id:"movies-592",text:"Think of me as Yoda. Only instead of being little and green, I wear suits and I'm awesome. I'm your bro. I'm Broda.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:115},{id:"movies-593",text:"Why, you stuck-up, half-witted, scruffy-looking nerf herder!",author:"Leia Organa",source:"Star Wars",category:"movies",license:"Fair Use",difficulty:"easy",length:60},{id:"movies-594",text:"Fear is the path to the dark side. Fear leads to anger; anger leads to hate; hate leads to suffering. I sense much fear in you.",author:"Yoda",source:"Star Wars",category:"movies",license:"Fair Use",difficulty:"medium",length:127},{id:"movies-595",text:"Granger? Granger? Can you possibly be related to Hector Dagworth-Granger, who founded the Most Extraordinary Society of Potioneers?",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"medium",length:131},{id:"movies-596",text:"Any road followed precisely to its end leads precisely nowhere. Climb the mountain just a little bit to test that it's a mountain. From the top of the mountain, you cannot see the mountain.",author:"",source:"Dune",category:"movies",license:"Fair Use",difficulty:"hard",length:189},{id:"movies-597",text:"Greatness is a transitory experience. It is never consistent. It depends in part upon the myth-making imagination of humankind. The person who experiences greatness must have a feeling for the myth he is in. He must reflect what is projected upon him. And he must have a strong sense of the sardonic. This is what uncouples him from belief in his own pretensions. The sardonic is all that permits him to move within himself. Without this quality, even occasional greatness will destroy a man.",author:"",source:"Dune",category:"movies",license:"Fair Use",difficulty:"hard",length:492},{id:"movies-598",text:"It was like the litany, she thought. We faced it and did not resist. We faced it and did not resist. The storm passed through us and around us. It's gone, but we remain.",author:"",source:"Dune",category:"movies",license:"Fair Use",difficulty:"hard",length:169},{id:"movies-599",text:"It occurred to Kynes that his father and all the other scientists were wrong, that the most persistent principles of the universe were accident and error.",author:"",source:"Dune",category:"movies",license:"Fair Use",difficulty:"hard",length:154},{id:"movies-600",text:"Deep in the human unconscious is a pervasive need for a logical universe that makes sense. But the real universe is always one step beyond logic.",author:"",source:"Dune",category:"movies",license:"Fair Use",difficulty:"medium",length:145},{id:"movies-601",text:"There is in all things a pattern that is part of our universe. It has symmetry, elegance, and grace - those qualities you find always in that which the true artist captures. You can find it in the turning of the seasons, in the way sand trails along a ridge, in the branch clusters of the creosote bush or the pattern of its leaves. We try to copy these patterns in our lives and our society, seeking the rhythms, the dances, the forms that comfort. Yet, it is possible to see peril in the finding of ultimate perfection. It is clear that the ultimate pattern contains its own fixity. In such perfection, all things move toward death.",author:"",source:"Dune",category:"movies",license:"Fair Use",difficulty:"hard",length:634},{id:"movies-602",text:"Kneel before me. I said... kneel! Is not this simpler? Is this not your natural state? It's the unspoken truth of humanity that you crave subjugation. The bright lure of freedom diminishes your life's joy in a mad scramble for power. For identity. You were made to be ruled. In the end, you will always kneel.",author:"",source:"The Avengers",category:"movies",license:"Fair Use",difficulty:"hard",length:309},{id:"movies-603",text:"But I hate that it seems you were never enough. We were broken and bleeding but never gave up. And I hate that I made you the enemy. And I hate that your heart was the casualty. Now I hate that I need you.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:205},{id:"movies-604",text:"Look at that subtle off-white coloring, the tasteful thickness of it. Oh my God. It even has a watermark.",author:"Patrick Bateman",source:"Psycho",category:"movies",license:"Fair Use",difficulty:"medium",length:105},{id:"movies-605",text:'"Did you put your name in the goblet of fire, Harry?" Dumbledore asked calmly.',author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"easy",length:78},{id:"movies-606",text:"A process cannot be understood by stopping it. Understanding must move with the flow of the process, must join it and flow with it.",author:"",source:"Dune",category:"movies",license:"Fair Use",difficulty:"medium",length:131},{id:"movies-607",text:"Remember! Reality is an illusion, the universe is a hologram, buy gold, bye!",author:"Bill Cipher",source:"Her",category:"movies",license:"Fair Use",difficulty:"easy",length:76},{id:"movies-608",text:"A darkness approaches. A day will come in the future where everything you care about will change... Until then I'll be watching you! I'll be watching you...",author:"Bill Cipher",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:156},{id:"movies-609",text:"Prince Zuko, you must look within yourself, and only then, can you save yourself from your other self.",author:"",source:"Avatar",category:"movies",license:"Fair Use",difficulty:"medium",length:102},{id:"movies-610",text:"Spread love wherever you go. Let no one ever come to you without leaving happier.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:81},{id:"movies-611",text:"Dreams make good stories, but everything important happens when we're awake.",author:"",source:"Dune",category:"movies",license:"Fair Use",difficulty:"easy",length:76},{id:"movies-612",text:"The trick, William Potter, is not minding that it hurts.",author:"",source:"Lawrence of Arabia",category:"movies",license:"Fair Use",difficulty:"easy",length:56},{id:"movies-613",text:"There are no more barriers to cross. All I have in common with the uncontrollable and the insane, the vicious and the evil, all the mayhem I have caused and my utter indifference toward it, I have now surpassed. My pain is constant and sharp, and I do not hope for a better world for anyone. In fact, I want my pain to be inflicted on others. I want no one to escape. But even after admitting this, there is no catharsis. My punishment continues to elude me, and I gain no deeper knowledge of myself. No new knowledge can be extracted from my telling. This confession has meant nothing.",author:"",source:"Psycho",category:"movies",license:"Fair Use",difficulty:"hard",length:586},{id:"movies-614",text:"I live in the American Gardens building on West 81st Street, on the 11th floor. My name is Patrick Bateman. I'm 27 years old. I believe in taking care of myself, in a balanced diet, in a rigorous exercise routine. In the morning if my face is a little puffy, I'll put on an ice pack while doing my stomach crunches. I can do a 1,000 now. After I remove the ice pack, I use a deep pore cleanser lotion. In the shower, I use a water-activated gel cleanser... then a honey-almond body scrub, and on the face, an exfoliating gel scrub. Then I apply a herb mint facial mask, which I leave on for ten minutes while I prepare the rest of my routine. I always use an aftershave lotion with little or no alcohol, because alcohol dries your face out and makes you look older. Then moisturizer, then an anti-aging eye balm, followed by a final moisturizing protective lotion. There is an idea of a Patrick Bateman. Some kind of abstraction. But there is no real me, only an entity, something illusory, and though I can hide my cold gaze and you can shake my hand and feel flesh gripping yours, and maybe you can even sense our lifestyles are probably comparable, I simply am not there.",author:"",source:"Psycho",category:"movies",license:"Fair Use",difficulty:"hard",length:1174},{id:"movies-615",text:"Alright. Let me ask you something. If the rule you followed brought you to this... Of what use was the rule?",author:"",source:"No Country for Old Men",category:"movies",license:"Fair Use",difficulty:"medium",length:108},{id:"movies-616",text:"Teach them our ways so they do not suffer the shame of being useless.",author:"",source:"Avatar",category:"movies",license:"Fair Use",difficulty:"easy",length:69},{id:"movies-617",text:"You can never cross the ocean until you have the courage to lose sight of the shore.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:84},{id:"movies-618",text:"One day it started raining, and it didn't quit for four months. We been through every kind of rain there is. Little bitty stingin' rain... and big ol' fat rain. Rain that flew in sideways. And sometimes rain even seemed to come straight up from underneath. Shoot, it even rained at night...",author:"",source:"Forrest Gump",category:"movies",license:"Fair Use",difficulty:"hard",length:290},{id:"movies-619",text:"Maybe someday we could become friends. Friends who ride majestic, translucent steeds, shooting flaming arrows across the bridge of Hemdale.",author:"Will Ferrell",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:139},{id:"movies-620",text:"We don't know what triggered the big bang, nor what, if anything, existed before it. But somehow the universe emerged as a vast sea of ultrahot gas, expanding fast in all directions like the fireball ignited by a nuclear bomb blast or by the explosion of a gas pipeline. Except that the big bang was not destructive (so far as we know). Instead, it created everything in our universe, or rather the seeds for everything.",author:"Kip Thorne",source:"Interstellar",category:"movies",license:"Fair Use",difficulty:"hard",length:420},{id:"movies-621",text:"You don't remember what happened. What you remember becomes what happened.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"easy",length:74},{id:"movies-622",text:"So when you run, make sure you run to something and not away from, 'cause lies don't need an aeroplane to chase you anywhere.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:125},{id:"movies-623",text:"Depend upon it there comes a time when for every addition of knowledge you forget something that you knew before. It is of highest importance, therefore, not to have useless facts elbowing out the useful ones.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:209},{id:"movies-624",text:"In the end, we will remember not the words of our enemies, but the silence of our friends.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:90},{id:"movies-625",text:"It is possible to fly without motors, but not without knowledge and skill.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"easy",length:74},{id:"movies-626",text:"Size matters not. Look at me. Judge me by my size, do you? Hmm? Hmm. And well you should not.",author:"",source:"Star Wars",category:"movies",license:"Fair Use",difficulty:"medium",length:93},{id:"movies-627",text:"Darkness cannot drive out darkness - only light can do that. Hate cannot drive out hate - only love can do that.",author:"Martin Luther King Jr.",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:112},{id:"movies-628",text:"If you can't fly, then run. If you can't run, then walk. If you can't walk, then crawl, but whatever you do - you have to keep moving forward.",author:"Martin Luther King Jr.",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:142},{id:"movies-629",text:"In this life we cannot do great things. We can only do small things with great love.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:84},{id:"movies-630",text:`You aren't a "broken wreck", Joshua. You're just scared, mostly because you care for people so much it breaks your heart… and you're lying to yourself about it. That's how I see it, and I know I'm right.`,author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:203},{id:"movies-631",text:"My fist is going to stop you, if you don't stop spouting nonsense and take this seriously.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:90},{id:"movies-632",text:"It is difficult to live in the present, pointless to live in the future and impossible to live in the past.",author:"Leto Atreides II",source:"Dune",category:"movies",license:"Fair Use",difficulty:"medium",length:107},{id:"movies-633",text:"At oh-eight-hundred hours, station time, the Romulan Empire formally declared war against the Dominion. They have already struck fifteen bases along the Cardassian border. So, this is a huge victory for the good guys. This may even be the turning point of the entire war. There's even a 'Welcome to the Fight' party tonight in the wardroom. So I lied, I cheated, I bribed men to cover the crimes of other men. I am an accessory to murder. But most damning thing of all, I think I can live with it. And if I had to do it all over again, I would. Garak was right about one thing. A guilty conscience is a small price to pay for the safety of the Alpha Quadrant, so I will learn to live with it. Because I can live with it. I can live with it. Computer, erase that entire personal log.",author:"Captain Benjamin Sisko",source:"Star Trek",category:"movies",license:"Fair Use",difficulty:"hard",length:782},{id:"movies-634",text:"Captain's log, stardate 57436.2. The Cerritos is docked at Douglas Station for routine maintenance and resupply. We will soon set course for the capital planet on the Galar system, where we're scheduled to make second contact with the Galardonian high council. First contact is a delicate, high-stakes operation of diplomacy. One must be ready for anything when humanity is interacting with an alien race for the first time. But we don't do that. Our specialty is second contact. Still pretty important. We get all the paperwork signed, make sure we're spelling the name of the planet right, get to know all the good places to eat.",author:"Ensign Bradward Boimler",source:"Star Trek",category:"movies",license:"Fair Use",difficulty:"hard",length:631},{id:"movies-635",text:"I've lost many friends. Some heroically, some tragically. The randomness of death is merely a reflection of the unexpected joys we find in life.",author:"Captain Hikaru Sulu",source:"Star Trek",category:"movies",license:"Fair Use",difficulty:"medium",length:144},{id:"movies-636",text:"You are one of my most valued officers and you are my friend. It is vital that you understand me here. I need you, but I also need to know that I can count on you. You are my counsel, the one I turn to when I need my moral compass checked. We have forged this relationship for years and I depend on it. I realize you made a sacrifice for me, but it's not one I would have allowed you to make. You can use logic to justify almost anything. That's its power, and its flaw. From now on, bring your logic to me. Don't act on it behind my back.",author:"Captain Kathryn Janeway",source:"Star Trek",category:"movies",license:"Fair Use",difficulty:"hard",length:539},{id:"movies-637",text:"If change is inevitable, predictable, beneficial; doesn't logic demand that you be a part of it?",author:"James T. Kirk",source:"Star Trek",category:"movies",license:"Fair Use",difficulty:"medium",length:96},{id:"movies-638",text:"Injustice anywhere is a threat to justice everywhere. We are caught in an inescapable network of mutuality, tied in a single garment of destiny. Whatever affects one directly, affects all indirectly.",author:"Martin Luther King Jr.",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:199},{id:"movies-639",text:"Mathematics, in an earlier view, is the science of space and quantity; in a later view, it is the science of pattern and deductive structure.",author:"Philip J. Davis",source:"Her",category:"movies",license:"Fair Use",difficulty:"medium",length:141},{id:"movies-640",text:"You gotta put your past behind you. Look, kid, bad things happen, and you can't do anything about it. Right? Wrong!",author:"",source:"The Lion King",category:"movies",license:"Fair Use",difficulty:"medium",length:115},{id:"movies-641",text:"Life wants to be lived, and I live it, even though it goes against logic. Very well, so I don't believe in the order of things, but the sticky leaf buds that open in spring are dear to me, as is the blue sky, as are certain people whom, would you believe it, sometimes one loves one knows not why.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:297},{id:"movies-642",text:"It was well received and reviewed, but the person who was really pleased with it was myself, for I knew better than any critic how difficult it had been.",author:"And Then There Were None",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:153},{id:"movies-643",text:"So, even though you have broken my heart yet again, I wanted to say, in another life, I would have really liked just doing laundry and taxes with you.",author:"",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:150},{id:"movies-644",text:"It is our choices, Harry, that show what we truly are, far more than our abilities.",author:"",source:"Harry Potter",category:"movies",license:"Fair Use",difficulty:"medium",length:83},{id:"movies-645",text:"I killed the Doctor for the notion of peace. For the notion that tyranny and evil must be fought, that the continued freedom of others was worth more than his life. And he wasn't the only one. So yes, I hope if I'm ever given the chance to end this war, I take it. Whatever the cost. However cruel it is in that moment, I pray I'm weak enough to sink to the level of my enemies. That I reject all I've ever stood for so that everything I've spent my lives defending can flourish again.",author:"Doctor Who",source:"Her",category:"movies",license:"Fair Use",difficulty:"hard",length:485},{id:"movies-646",text:"Interestingly, according to modern astronomers, space is finite. This is a very comforting thought-- particularly for people who can never remember where they have left things.",author:"Woody Allen",source:"Speech or Publication",category:"movies",license:"Fair Use",difficulty:"hard",length:176},{id:"movies-647",text:"It seemed the world was divided into good and bad people. The good ones slept better... while the bad ones seemed to enjoy the waking hours much more.",author:"Woody Allen",source:"Speech or Publication",category:"movies",license:"Fair Use",difficulty:"hard",length:150},{id:"movies-648",text:"Eternal nothingness is fine if you happen to be dressed for it.",author:"Woody Allen",source:"Speech or Publication",category:"movies",license:"Fair Use",difficulty:"easy",length:63},{id:"movies-649",text:"I took a speed-reading course and read 'War and Peace' in twenty minutes. It involves Russia.",author:"Woody Allen",source:"Speech or Publication",category:"movies",license:"Fair Use",difficulty:"medium",length:93},{id:"movies-650",text:"I'm astounded by people who want to 'know' the universe when it's hard enough to find your way around Chinatown.",author:"Woody Allen",source:"Speech or Publication",category:"movies",license:"Fair Use",difficulty:"medium",length:112},{id:"movies-651",text:"His lack of education is more than compensated for by his keenly developed moral bankruptcy.",author:"Woody Allen",source:"Speech or Publication",category:"movies",license:"Fair Use",difficulty:"medium",length:92},{id:"movies-652",text:"Life is divided into the horrible and the miserable.",author:"Woody Allen",source:"Speech or Publication",category:"movies",license:"Fair Use",difficulty:"easy",length:52},{id:"movies-653",text:"I can't listen to that much Wagner. I start getting the urge to conquer Poland.",author:"Woody Allen",source:"Speech or Publication",category:"movies",license:"Fair Use",difficulty:"easy",length:79},{id:"movies-654",text:"How is it possible to find meaning in a finite world, given my waist and shirt size?",author:"Woody Allen",source:"Speech or Publication",category:"movies",license:"Fair Use",difficulty:"medium",length:84},{id:"movies-655",text:"I don't want to achieve immortality through my work... I want to achieve it through not dying.",author:"Woody Allen",source:"Speech or Publication",category:"movies",license:"Fair Use",difficulty:"medium",length:94},{id:"movies-656",text:"I was thrown out of college for cheating on the metaphysics exam; I looked into the soul of the boy sitting next to me.",author:"Woody Allen",source:"Speech or Publication",category:"movies",license:"Fair Use",difficulty:"medium",length:119},{id:"movies-657",text:"If it turns out that there is a God, I don't think that he's evil. But the worst that you can say about him is that basically he's an underachiever.",author:"Woody Allen",source:"Speech or Publication",category:"movies",license:"Fair Use",difficulty:"medium",length:148},{id:"movies-658",text:"It is impossible to experience one's death objectively and still carry a tune.",author:"Woody Allen",source:"Speech or Publication",category:"movies",license:"Fair Use",difficulty:"easy",length:78}];export{e as default};
